local _, ns = ...

-- Progress (p) and hand-in (c) texts for quests whose other texts are in Data_Quests.lua
local extra = {
  [86585] = {c="Fandt du Ylvas lig? Ah, stakkels kvinde. Hun sagde, at hun ville vise troggerne, at Jernsmede aldrig vil falde for deres slægt. Hun var på vej for at lede efter nogle bjergfolk, der aldrig vendte tilbage fra patruljen over troggernes land. Hun var altid for uafhængig til at være forsigtig. Nu ved vi, hvad der skete.\n\nJeg tager banneret og sørger for, at det bliver renset og udstillet. Du bør tage hendes våben. Må det tjene dig godt mod troggerne.", p="Dette banner ser ud, som om det har været igennem krig!"},
  [86614] = {c="Mit hårspænde! Jeg troede, at det var væk for altid!\n\nDet vil skinne smukt efter lidt arbejde. Tak, fordi du bragte det til mig! Jeg er dig taknemmelig.", p="Jeg har mange ærinder at tage mig af i dag, kan du gøre det hurtigere?"},
  [86667] = {c="Er den krukke til mig?\n\nSne! Grenhilde gjorde det! Hun sendte sneen, jeg bad om!\n\nSkade, jeg håbede, at hun selv ville komme forbi.\n\nÅh, i hvert fald, du har nok fortjent noget for din indsats. Her har du.", p="Hæ? Hvad vil du?"},
  [86758] = {c="Ha! Du gjorde det! Jeg troede aldrig, at den gamle krokodille skulle stå til regnskab for sine gerninger, men det klarer sagen!\n\nOh ah... du ved, jeg måtte skaffe mig en anden kniv, men denne her kan måske bringe dig held. Hvorfor beholder du den ikke?", p="Hvordan går jagten?"},
  [86776] = {c="Ah, en lettelse! Jeg burde kunne holde smedjen i gang nu. Jeg håber, at vi engang får en handelsmand, der regelmæssigt leverer kul til byen!", p="Jeg må holde smedjen i gang!"},
  [86784] = {c="Ekstra brænde? Det kommer altid til nytte. Det holder de gamle knogler varme gennem de kolde nætter i Skoven.\n\nJeg har mit eget reb til at samle brænde, så du må gerne beholde kurven.", p="Velkommen ved min ild, vandrer."},
  [87318] = {c="Kolma sendte dig? Det er den bedste nyhed!\n\nDa Mørkjernerne overraskede os, blev vi adskilt, og jeg slog hovedet og kunne ikke finde ud af, hvilken vej jeg skulle gå. Jeg endte her og har levet af forrådet fra min taske i flere dage. Nu da du har formået at komme forbi Mørkjernerne, kan jeg måske slippe væk.\n\nJeg skal bare samle mine ting og tage en pause, så finder jeg på en måde at komme væk!\n\nHun har aldrig forladt mig. Sikke et fantastisk hjerte."},
  [87760] = {c="Det var en lang rejse, Appelsinrystelse, men den var det værd.\n\nDu fik endelig fat i staven, som nagaerne bruger til at tvinge havskabninger i deres tjeneste. Jeg vil sørge for, at den bliver ødelagt, så mørlokkerne og havskildpadderne endelig kan leve i fred.\n\nTak igen. Din udholdenhed er endelig blevet belønnet, og jeg er personligt taknemmelig over for dig.", p="Endelig får vi løst gåden, og dyrene får fred!"},
  [88756] = {c="Ak, det er en sten fra hjertet. I hvert fald kan Mørkejernene ikke trille bomben hen til vores vogne... eller smide den i katapulten... eller rulle den ned ad bakken mod os... eller fodre slimerne med den og så sende dem ind i vores lejr og sætte ild til dem.\n\nNu skal vi bare sørge for, at kruttet er tørt!\n\nTak!", p="Denne krig med Mørkjernerne trækker og trækker i langdrag!"},
  [90902] = {c="Smerte er ikke noget nyt for dem, der har overlevet døden, og derfor er De Forladte særligt modstandsdygtige over for den. Smerten har også en renselsende karakter, som du bør tage til dig som en æresbevisning og et bevis på, at du stadig er et tjenende lys på trods af dine nye omstændigheder.\n\nVær velsignet og gå igen i lyset, YOUR_CLASS7.", p="Mesterskabet i Lyset vender tilbage, med tiden."},
  [91208] = {c="Tragisk nok bliver langt flere af vores brødre og søstre gale på samme måde, efter at de er blevet rejst. Så dyrebar hver eneste de Forladtes sjæl er, er det nogle gange det bedste, vi kan gøre for dem, der ikke kan finde sig til rette, at give dem en ren ende.\n\nJeg beder til lyset for hende. Tak fordi du gjorde det, der måtte gøres, Kældorn."},
  [91209] = {c="Velkommen om bord, YOUR_CLASS7. Det er altid opmuntrende at se flere af vores tal rende rundt i disse egne. Der er mange her i Gryde-by, som har brug for hjælp fra eventyrere som dig. Søg arbejde og bliv stærkere i Lyset. Kom tilbage til mig, når du har brug for undervisning.\n\nNår du har bevist dig selv og Gryde-by's folk, vil jeg vejlede dig til næste trin på din rejse.\n\nGå med Lyset, YOUR_CLASS7."},
  [91282] = {c="Endnu en frisk rekrut? Velkommen til Tyrs Vagt, broder."},
  [91285] = {c="Tak for hjælpen. Jeg er sikker på, at det ikke stopper angrebene helt, men jeg håber, at det gør dem lidt langsommere. Det er svært nok at genopbygge dette sted, uden at en mudderlok forsøger at stikke dig i ryggen med sit spyd."},
  [91294] = {c="Breton sendte dig herhen, eh? Fortrinligt.\n\nJeg er Danitha Mør, og jeg er en slags kommandant for denne fæstning. Hvis du kommer og søger fællesskab blandt dem, der stadig er loyale over for Lyset, har du ramt det rette sted.\n\nDer er meget arbejde foran os, før vi er fuldt etablerede, og vi ville være taknemmelige, hvis du ville hjælpe os.", p="Velkommen til Bandarion-borgen, YOUR_CLASS7. Det er altid godt at se et nyt ansigt."},
  [91316] = {c="Jeg er glad for, at din rejse til Skyggedalen har båret frugt. Jeg sender Breton og et par andre nye rekrutter derud senere for at rydde resten af kælderen og pille alt, der er tilbage i mørket, ud af det.", p="De siger, at placering er alt. Selvom fæstningen kan se imponerende ud, klynget til disse klipper, viser det sig, at det er en ret stor udfordring at holde den forsynet så langt fra ordentlig civilisation. Desværre vores forsømmelse."},
  [91317] = {c="Godt arbejde, Kola. Hver gang en af de Plettede slår og dræber en af de Forladte, bliver det meget lettere for vores kritikere at så mistillid til os korsriddere. At udrydde dem vil støtte vores sag og styrke vores stilling her i Tirisfal.\n\nJeg formoder, at det kan tage lang tid, før vi bliver fuldt accepteret af de Forladte og Horden. Det kan tage år... eller måske endda årtier, men det er det bedste, vi kan gøre: at blive ved med at bevise os selv over for os selv.", p="De Plettede truer den lille støtte, vi har fra de andre Forladte. Selvom det smerter mig at krydse klinger med vores tidligere brødre og søstre, må de standses, hvis vores spæde orden skal overleve."},
  [91723] = {c="Godt gjort, min ven. Lad mig prøve mine kalibreringer igen..."},
  [91724] = {c="Det ser ud til, at alt virker, som det skal. Tak, Tykke."},
  [91725] = {c="Åh, hvor er jeg lettet! Det ser ud til, at det hele er her. Tak!", p="Har du fundet ressourcerne?"},
  [91732] = {c="Åh, meget flot. Ser du glansen? Virkelig, sådan laver de ikke længere.", p="Har du allerede været i minen?"},
  [91733] = {c="Du ser en smule våd ud, Urjen. Undskyld for det. Men tak for at hente forsyningerne tilbage.", p="Har du fundet forsyningerne?"},
  [91741] = {c="Hov! Hvor har du den fra? Den skulle have stået på hylden! Åh nej, kobolderne stjæler mine bøger igen. De må have lyst til at spise dem!\n\nTak for at bringe bogen, men hvad skal jeg gøre med resten af min forsvundne samling?", p="Hvad har du dér? Det ligner en af mine bøger."},
  [91743] = {c="Mange tak! Her! Tag en af disse vejledninger. Jeg har ikke brug for dem.\n\nMen der mangler stadig så mange bøger til mig. Kobolderne ser ikke ud til at spise dem. Hvorfor vil de så have dem?", p="Har du allerede reddet mine bøger, Braiknok?!"},
  [91745] = {c="Kobolder med bøger? Jo, jeg har set kobolder løbe frem og tilbage med bøger, mens de skriger ad hinanden. De må stjæle dem fra biblioteket inde i klosteret."},
  [91751] = {c="Fremragende indsamling af disse pelse, YOUR_CLASS7. Du har et ægte talent for jagt.", p="Har du heldet med dig til ulvepelsene?"},
  [91752] = {c="Tak for at returnere de stjålne bøger, Jødekong. Jeg giver dem straks tilbage til Bror Fredton.\n\nDu er ved at blive en helt her på stedet. Flot arbejde!", p="Har du allerede fået de tyvstjålne bøger tilbage?"},
  [91753] = {c="Teori og praksis er to sider af samme mønt, Rygsprængeren. Husk det.", p="Hvad afslørede dine studier?"},
  [91758] = {c="Jeg kan hjælpe dig med at spore det skadedyr. Lad mig forberede noget til dig."},
  [91772] = {c="Hvad er det, Kalerenn? Sporing af kobolder?\n\nJa, de er selvfølgelig på vej mod Fjerndyb-minen! Stedet er inficeret af kobolder.\n\nGodt gået, synes jeg. Jeg får brug for nogen til at tage sig af det problem.", p="Har du allerede opdaget, hvor kobolderne er på vej hen?"},
  [91775] = {c="Jeg beundrer din flid, Pawtrik. Broder Paxton sendte en liste over bøger, og du har fundet de fleste af de forsvundne. De resterende må være taget med til Jaspisåre-minen.\n\nDu må gerne beholde den bogpose!", p="Har du fundet alle bøgerne endnu?"},
  [91777] = {c="Åh, Kritofer! Tusind tak for at redde mit bibliotek. Du har gjort mig en vanvittig tjeneste. Tag nu et af de fede våben, vær sød. De var beregnet til militsen, men du kan bruge dem bedre.", p="Har du fundet alle mine bøger endnu?"},
  [91858] = {c="Danitha sendte dig? Nå, så ved jeg da hvorfor du er her. Du er lige røget ind i en helvedes ballade, YOUR_CLASS7."},
  [91861] = {c="Er du en af de Forladte, ikke? Kan du hjælpe mig med at komme fri?\n\nJeg er bange for, at tiden løber fra mig. Skynd dig, venligst!"},
  [91920] = {c="Eliksiren virkede ikke? Selvfølgelig virkede den ikke. Du bragte mig for få hjerter. Opskriften kræver seks. Du bragte tre.\n\nDog må jeg indrømme, at jeg ikke overvejede en anvendelse for murlok-dele, før nu...\n\n<Renfærrel tager øjnene.>\n\nJeg har råd til at ofre nogle af mine egne hjerter for at genvinde din Dødsstalkers styrke.", p="Åh. Er du tilbage?"},
  [91921] = {c="<Kvinde tager en eliksir og drikker den.>\n\nJa, jeg kan mærke, at den virker. Snart kan jeg rejse igen.\n\nDu har gjort mig en stor tjeneste, Saixgå.", p="Du er tilbage! Jeg var ved at forsone mig med at degenerere til en ghul."},
  [92110] = {c="Du har bragt mig murlocøjne! Jeg er så ophidset over min første ÆGTE eliksir, at jeg ikke kan trække vejret!\n\nJeg trak mig tilbage og greb nogle flere urter, mens du var på vej, og fandt tomme phialer nede i bunden. Hmm... du må gerne blande denne gang.\n\n<Barnet ser entusiastisk til, mens du blander ingredienserne, men hendes næse krøller sig, da du tilføjer øjnene. Blandingen får en sygeligt orange farve i løbet af få sekunder.>\n\nWow! Se, jeg havde ret. Jeg ville ikke drikke det, men her er min opskrift, hvis du vil lave mere. Kom tilbage engang!", p="Bekymr dig ikke om mig, jeg er en stor pige. Jeg kan passe på mig selv. Bare fortæl ikke nogen, at jeg gemmer mig her, det er vores lille hemmelighed."},
  [92124] = {c="Ja, jeg har hørt. Jeg advarede Broder Paksøn tre gange om kobolderne, der gravede tunneller under klosteret.\n\nDet ser ud til, at kobolderne har taget mange bøger. Der er hele hylder tomme. Du bør nok se, hvad Broder Paksøn vil have, at du gør ved det.\n\nMens du er her, kan jeg så snakke med dig om handelsfærdigheder? Jeg besvarer gerne de spørgsmål, du måtte have, eller henviser dig til de lokale trænere."},
  [92401] = {c="Det jeg bad dig om, var ikke retfærdigt, og det ville det heller ikke være, hvis du bare gik videre. Tak, ven. Jeg kan ikke gengælde det lige så meget, men jeg håber, at en af de her ting vil være acceptabel.\n\nJeg håber, at vores veje krydser hinanden uden sådan en sorg."},
  [92415] = {c="Hjertevæver? Hjertevæver...\n\nÅh! Den lille Jeremy Hjertevæver. Han blev bragt hertil for år tilbage efter angrebet på Herrelande. Han mistede begge sine forældre i angrebet, stakkels dreng.\n\nHan blev for nylig adopteret af en venlig kvinde i Skumringsskoven.", p="Hvad er der, Stor? Hvad leder du efter?"},
  [92421] = {c="Må dem, der falder i Dødsånd-dronningens unåde, møde vores retfærdighed!\n\nMed disse dele håber vores brødre og søstre at se endnu en dag. Du ærer kaptajn Bandarion med stolthed.", p="Hvad er der tilbage af den angribende Pest? Fandt du de rette reservedele?"},
  [92422] = {c="Selvom jeg ikke tvivler på, at noget af hans slags vil blive erstattet, kan vi håbe, at deres rækker tynder ud i mellemtiden.\n\nTak, Død."},
  [92434] = {c="Det er bestemt ingen tilfældighed, at Horden har fået så stor interesse for min by på så usikre tider.\n\nFaktisk regnede jeg med det. Jeg har et forslag til dig.", p="Læg våbnet fra dig, YOUR_RACE7.\n\nJeg tror ikke, nøglen er nok til at komme forbi mine beskyttelsesbesværgelser. Troede du virkelig, at vi ville lade sådan et hul stå åbent i så farlige tider?"},
  [92460] = {c="Hilsen fra Kuling, Uønsket. Jeg har den ære i dag at tildele dig din modenhedsamulet, fordi du er blevet genkendt for det potentiale, du bringer til shen'dorei. Vores folk har lidt store smerter og forfølgelse i vores komplekse historie.\n\nI dag modtager du denne amulet, som er en af de mange, der er blevet båret af dem, der var før dig. En dag, når din aske bliver spredt for vinden, vil den gå videre til en anden for at fortsætte vores tradition.\n\nNår du tager denne amulet med dig, så vid, at hjemmets vinde vil følge dig, hvor end du rejser hen."},
  [92461] = {c="Tak for din tjeneste for Vindras, unge YOUR_CLASS7.\n\nVuldrener er normalt ganske lydige, men dyrene, der kalder Vindras for hjem, kan mærke, når magien i vindene er ude af balance, hvilket kan føre til farlig og uforudsigelig adfærd, hvis de efterlades uden kontrol."},
  [92462] = {c="Ud fra mængden af insektindvolde, der dækker dig, må det være en ganske betydelig smitte.", p="Sådanne skadedyr må ikke sive ind i vores fredelige lund. Smitten kan hurtigt blive farlig, hvis man lader den løbe løbsk."},
  [92463] = {c="Godt gået, Hundelufter. Du ville være en god ranger, hvis det ikke var for hele det med at være eventyrer.", p="Cirrusfluer må ikke undervurderes. De virker måske ikke farlige, men du skal passe på de større. Jo større, jo mere ondskabsfulde!"},
  [92464] = {c="Rorian sendte dig? Godt. Jeg kunne bruge din hjælp."},
  [92465] = {c="Det smerter mig at udgyde Stjernebørn-blod her i lunden, men vi gør, hvad vi må."},
  [92466] = {c="Du er vendt tilbage og har bragt det, jeg bad dig om. Din viljestyrke og beslutsomhed er ubestridelig. Du er klar til næste skridt, Harten.", p="Al'Aketh-kulten udgør den seneste og mest presserende trussel mod vores hjemland. Deres stadig mere ekstreme handlinger har destabiliseret vores samfund, og vi har beskadiget vores allerede svækkede forbindelse til de fire vinders ånder. Elementerne kræver handling for at bevise vores modstandsdygtighed og beslutsomhed, som er karakteristiske træk ved jordelementets rige."},
  [92467] = {c="Ah... Frøsterz... vindenes fire barn... Du søger forståelse. Du søger svar. Hvorfor har vindene forladt dig? Hvordan kan du genvinde dem? Det er svar, jeg ikke kan give, for jeg kender ikke vindenes motiver eller bevægelser.\n\nJeg kan dog lære dig meget om jorden. Dens styrke, dens beslutsomhed. Selv her, højt oppe i dette endeløse hav af skyer, er du stadig et jordens væsen. Hvis du håber at finde styrke til at tale med de fire vinds ånder igen, er det en sti, du må gå."},
  [92468] = {c="God!\n\nTotemet, som jeg smeder til dig, er mere end et symbol på din status blandt YOUR_CLASS7 - det har også evner ud over det. Et af totemets anvendelser er at samle besværgelser. Disse besværgelser er knyttet til jorden, og efterhånden som du får mere og mere visdom, står flere jordevner til din rådighed.\n\nLærerne vil vide, hvornår du er klar til mere viden.\n\nMen indtil videre, tag dette jordtotem...", p="Som du vil lære, er stien, vi går, ikke så ligetil, som den måske virker. Selvom vi søger den stemme, der er nødvendig for at tale med vindens ånder, er vinden kun en af verdens elementære kræfter. Kun ved at forstå og - vi håber - mestre alle fire elementer vil vi genfinde vores stemme, så vi igen kan synge vindens sange."},
  [92469] = {c="Det er meget foruroligende, men desværre ikke overraskende. Vi har været klar over kultens bevægelser i noget tid, men vi har været tilfredse med at betragte det på afstand. Deres opildning af vindånder nær de stående sten er en tydelig optrapning fra deres side.\n\nDu har udført en svær, men nødvendig tjeneste for Thendal-lunden, Ranør. Tak."},
  [92470] = {c="Godt gået. Du har fældet bestierne og besejret indtrængerkultisterne. Du har vist stort potentiale, men din vej må snart føre dig væk fra den relative sikkerhed i Thendal-landsbyen.", p="Det jeg beder dig om, er ikke let, men du må være forberedt på langt større udfordringer, hvis du vil overleve længe nok til at være til nytte for Vindras-øen."},
  [92471] = {c="Rorian fortalte mig meget om dig. Jeg er sandsynligvis ukendt for dig, men jeg er medlem af Rådet for de Ældste her på Vindras-øen. Jeg er kommet for at læse vindstrømmene her i Thendal-lunden. Jeg er også her for at vurdere unge shen'dorei som dig, der er ved at modnes.\n\nSå fortæl mig, er du klar til at tage næste skridt? Er du parat til at tjene Vindras-øen?"},
  [92472] = {c="Så Aetheen har sendt dig? Jeg må indrømme, at du ikke ser ud af meget for mig, men Shen'dar-landsbyen afviser ikke hjælp fra villige hænder, endsige hjælp sendt direkte fra Ældre Aetheen selv."},
  [92473] = {c="Fint klaret, YOUR_CLASS7. Gaju-rangerne står i din gæld.", p="Bjørnseraerne er blevet langt mere aggressive på det seneste. Jeg undrer mig over, hvad der har ændret sig, så adfærden er skiftet på den måde?"},
  [92474] = {c="Hvor mange gange har jeg skullet sige til Mirjaal, at han ikke skal opfordre andre til at bruge vores himmelbårne gaver uden eftertanke!\n\nDet sagt synes jeg, at lidt øvelse i landsbyens relative sikkerhed er... acceptabelt.\n\nFremover vil jeg blot råde dig til at bruge din evne fornuftigt. Du vil ikke udtømme din magi uden at tænke over det og så ikke være i stand til at bruge den, når du virkelig har brug for den.", p="Ved at bruge din evne til at gå på luften kan du komme ud af - og tja... alle slags problemer!"},
  [92481] = {c="Lad mig se dig an. Ja, jeg tror, du bliver en fremragende ung YOUR_CLASS7. Arkanens kraft er blevet svækket blandt vores folk, men der er dem, der gerne vil genopdage meget af det, vi har mistet i de årtusinder, vi har tilbragt her blandt skyerne. Jeg er sikker på, at du vil lede denne endeløse søgen efter arkan viden og til sidst ære os.\n\nTal med mig igen, hvis du ønsker at fortsætte.", p="Hej, Derek. Jeg er glad for at have æren af at udvikle dine magiske studier."},
  [92482] = {c="Vejen for en YOUR_CLASS7 er fuld af farer, og kun dem med de skarpeste sanser og hurtigste reflekser kan trives i det vilde. Jeg ser på dig og husker mig selv, da jeg stod foran min mentor for mange år siden. Jeg tror, du har det, der skal til, men i sidste ende er det kun op til dig.\n\nTal med mig igen, hvis du vil fortsætte.", p="<Tai'ree nikker kort i enighed.>"},
  [92483] = {c="Jeg hørte næsten ikke, at du nærmede dig, unge YOUR_CLASS7.\n\nNæsten.\n\nNæsten er ikke nok, når du forlader Thendal-lunden. Du skal være et tyndt sværd, stille og sikker. Altid årvågen og altid bevidst om dine omgivelser. Du kan have det, der skal til for at overleve farerne i Vindras. Du kan også ende med din hals skåret over i en grøft. Til sidst er det helt op til dig.\n\nTal med mig igen, hvis du ønsker at fortsætte.", p="<Akeri ser mistænksomt på dig.>"},
  [92484] = {p="Vindene leder dig, Vindar."},
  [92485] = {c="Flora og fauna på Vindras-øen udgør et rigt mosaik af den levende verden. Økosystemet kræver konstant balance for at bevare naturens harmoni, og vi druider er vogtere af denne balance. Jeg ser et stort potentiale i dig, men denne vej er ikke let, og du vil få brug for en vejleder, efterhånden som du bliver stærkere som elev af hugtand, klo, fjer og gren.\n\nTal med mig igen, hvis du ønsker at tage de næste skridt.", p="Hilsen, jeg er Xyton Sølvvind, vogter af druidisk viden."},
  [92514] = {c="Har du været hos Illaya? Storartet. Der har været en del spænding mellem Højordenen og Vindformerne på det seneste, men her forbliver de civiliserede.\n\nNu hvor det er overstået, ser du ud som en, der leder efter noget at lave, og jeg har et banditproblem, du måske kunne hjælpe mig med."},
  [92515] = {c="Jeg sagde da vel ikke, at det ikke ville blive et beskidt job, vel?", p="Hvis du spørger mig, så synes jeg faktisk, at Stolthedens Erobrere er ret pæne. Fra en sikker afstand... og stående bag en, der holder et sværd, selvfølgelig."},
  [92516] = {c="Godt gjort, og hurtigt også. Slet ikke dårligt."},
  [92517] = {c="Nu hvor banditterne er spredt, er det ét problem mindre for os. Dog indrømmer jeg, at jeg nu bekymrer mig om, at de banditter, der overlevede, måske søger ly hos kulten og yderligere øger deres allerede foruroligende antal.\n\nMen vi tager sejre, hvor vi kan få dem."},
  [92528] = {c="Var Lorthuna selv derude? Hun er lederen af hele den fordømte kult!\n\nHvis de gør et træk mod Shen'dar-landsbyen og det vestlige udkigstårn, må vi være parat. Hvilket er mærkeligt... hvorfor tårnet?\n\nLandsbyen kan jeg forstå, men et tårn? Det har ikke megen strategisk betydning, bortset fra et lille udkigspunkt.\n\nUanset hvad, så er vi klar. De vil opdage, at højlænderne ikke lader sig overraske så let, som de måske tror.", p="Hvad fik du at vide?"},
  [92529] = {c="Hvad er det? En ny novice, der vil tjene vindherren, sendt af søster Sania? Vi er virkelig velsignede af de fire vinders berøring i dag!\n\nVelkommen alle, der søger Al'Akirs velsignelse."},
  [92532] = {c="Du er ved at begive dig ud på en farlig rejse. Vores verden forandrer sig, og den vil have brug for dem, der har viljen til at lede og beskytte andre, hvis vores folk skal have en chance for at overleve. Efterhånden som du bliver stærkere, får du brug for en vejleder. Kom til mig - jeg vil gøre alt, hvad jeg kan, for at træne dig, efterhånden som du udvikler dig.\n\nHeld og lykke, Vindelriel, må vindene lede dig.", p="Så du er kommet til træning, ja?"},
  [92544] = {c="Jeg kunne ikke lade være med at gå derhen og slutte mig til dig fra min position her. Jeg kan kun håbe, at skurkene har forstået budskabet og snart pakker sammen.\n\nTak, YOUR_CLASS7. Du har Thendal-lundens Vogteres taknemmelighed."},
  [92550] = {c="Tak, vinde, fordi du er kommet tilbage!\n\nSania Sølvstrøm slap ud af byen lige før din tilbagekomst, uden tvivl på flugt, da vores folk væbnede sig.\n\nDu har gjort noget fantastisk for folkene i Shen'dar-landsbyen, og vi står i gæld til dig. Hvis kulten vender tilbage til højlandet, vil de opdage, at Shen'dar ikke er et så nemt mål.\n\nMå vindene føre dig, Vindelriel.", p="Det føles godt at vende rollerne over for de her fanatikere."},
  [92551] = {c="Det er fantastisk! Vi klarer knap nok uden vores faste forsyninger. Jeg vil arbejde sammen med konstablen for at sikre, at forsyningerne bliver omfordelt til de indbyggere, der er i størst nød.", p="Her er mange sultne og fortvivlede himmelbårne, som har brug for disse forsyninger."},
  [92553] = {c="De æg er ikke lette at skaffe, men så sandelig vindlorden være med mig, de er LÆKRE stegt i en smule bjørnefedt.\n\nHvis du har lidt tid og kan lide at lave mad, kan jeg lære dig nogle af de kneb og tricks, jeg har samlet. Sig til, så træner jeg dig gerne.", p="Uanset hvor meget der forandrer sig her i Vindras, og hvor usikkert det bliver, siger jeg altid, at en pibe fyldt med tørret roligt blomst og en god mæt mave er en fornøjelse, der ikke kan overgås!"},
  [92579] = {c="<Valennias ansigtsudtryk mørkner, når hun læser brevet.>\n\nAonda stolede på, at du ville levere det, og hun taler godt om dig i brevet, så jeg vil forsøge at stole på dig. Før vi taler videre, må jeg konsultere et par af de fredsbevarere, der er tilbage, og lægge en plan for, hvad der sker, hvis kulten angriber her næste gang. Nyd indtil videre opholdet i Valanår.\n\nHvis du leder efter noget at tage dig til, er der mange byfolk, som nok kan bruge hjælp fra en stærk ung eventyrer som dig.", p="Brev fra Aonda. Hvad har den kløgtige bjergmand mon været i gang med?"},
  [92595] = {c="Jeg tror, du nu forstår, hvor vigtig Vindformernes mission er. Hver sjæl, der befaler Himmelsyn, er livsvigtig, hvis vi håber på at genoptage dialogen med vindånderne.\n\nMellem truslerne indefra, som Al'Aketh, og usikkerheden om vores sikkerhed her i Himmelmuren, er det vores ansvar som Vindformere at bruge vores gaver til at redde vores hjem og sikre, at Stjernebørn kan overleve disse svære tider.", p="Verden forandrer sig, og vejen frem bliver svær. Vi har kun én chance for at redde os selv."},
  [92596] = {c="Højordenens mission er yderst vigtig for vores folks overlevelse. Vi holder vores elementære velgørere i højeste ære, men vi må se virkeligheden i øjnene; de er gået bort nu, og vi er alene.\n\nMellem truslerne indefra, såsom Al'Aketh, og usikkerheden om vores sikkerhed på dette plan, er det vores skæbne som efterkommere af de Højfødte fra vores gamle hjemland Eldre'Thalas at bruge vores gaver til at sikre, at Stjernebørnene igen kan stå på egne ben.", p="Vores land gennemgår forandringer, men det kan stadig blive godt af det."},
  [92597] = {c="Mærker du det? Ja? Godt! Du har taget dine første skridt. Du vil opdage, at du med dine evner kan banke på skjult magisk energi mange steder. Det vil give dig en masse gavn, nogle dybe, andre mere subtile. Du vil ikke vide det, før du har banket på dem, men det er den bedste del af gaven... at gøre det ukendte kendt.\n\nSkal vi overleve de frygtelige tider, må vi være ubøjelige i vores søgen efter viden... og magt."},
  [92598] = {c="Ligesom en muskel skal dit himmelsyn trænes, hvis du håber at vokse stærkere i gaven. At bruge dit himmelsyn til at bygge bro over afstanden mellem det dødelige og det åndelige kan vise sig uvurderligt på dine eventyr.\n\nDu bør huske godt, hvad du har lært her i dag. Vores evne til at bruge vores gaver til at lytte til, hvad elementerne fortæller os, kunne være nøglen til vores overlevelse."},
  [92640] = {c="Spændingerne mellem Vindformerne og Højordenen er nu høje, men vi kunne ikke have håbet på at gennemføre denne plan uden begge grupper om bord."},
  [92642] = {c="Er du stadig i live? Jeg takker vindene for de små mirakler, må jeg antage."},
  [92643] = {c="<Manden er åbenlyst død, dræbt af skurkene, du kæmpede med foran huset. Mens du knæler for at undersøge liget, bemærker du et skinnende glimt af noget blankt...>"},
  [92644] = {c="Forræderen var allerede død, da du ankom, siger du? Det er uheldige nyheder.\n\n<Du rækker krystallen, du fandt på kultistforræderens døde krop.>\n\nInteressant...", p="Er du tilbage? Og... alene?"},
  [92645] = {c="Belguilos er død? Fire vinde velsigne dig, YOUR_CLASS7.\n\nVi må bare overleve det hele."},
  [92646] = {c="Jeg sendte nogle af vores healere for at sikre, at Valennia og hendes øvrige styrker kom tilbage i ét stykke. Hun burde ligge og slappe af i Den Høje Ældstes residens nu.\n\nMuldvarp er allerede taget tilbage til Azeroth, men vi har alle talt om, hvad der er næste skridt for Vindformerne og vores mission på Azeroth. Desværre er øen nu mere sårbar over for alt end nogensinde, og vi har brug for en plan for at beskytte Vindras mod det, der kommer."},
  [92679] = {c="<Amelie lytter, mens du forklarer Alvarion, hvad der skete.>\n\nI det mindste ved jeg, at han vil være i sikkerhed i Valanår.\n\nFremmede, jeg hader at sige det til dig, men jeg tror, min idiot af en mand lige har sendt dig herud for at dø for ingenting. Hvis du har en smule fornuft i dig, bør du gå nu. Dette er ikke din kamp.", p="Hvad? Lever Alvarion?"},
  [92682] = {c="Jeg så dig slå de røvere ned fra vinduet. Ikke dårligt.", p="De banditter forråder og bestjæler hinanden langt oftere, end de bestjæler almindelige folk. Jeg vil vædde på, at hvis Ferauu vidste, at nogle af hans folk har gjort oprør og kom herhen tidligere for at pille ved høsten, ville han selv slå dem ihjel."},
  [92683] = {c="Dette stof kan være lidt rodet og har en tendens til at være overalt. Du kommer nok til at ryste det ud af bukserne i ugevis, desværre. Men jeg sætter meget pris på det. Det har stået på min huskeliste i ugevis, men at gå for langt væk hjemmefra, når jeg er alene med banditterne, der lurer overalt, er en stor risiko.\n\nSpørg mig ikke, hvad det bruges til. Ting. Ting og sager. Tænk ikke mere over det.", p="Luftsommerfuglene er normalt milde og rolige, men rør dem på den rigtige måde, så overrasker de dig nogle gange."},
  [92684] = {c="Det er store mørbrad! Du må have kæmpet mod virkelige monstre derude.", p="Jeg tror ikke, jeg har spist rigtigt kød til middag siden... tja, alt for længe."},
  [92685] = {c="Da jeg sagde mere blodigt, lyttede du virkelig. Godt. Det fortæller mig, at du har givet dem ondt.\n\nSeriøst, tak for det du har gjort indtil nu. I ugevis har jeg drevet rundt på denne gård uden mål, som om jeg ventede på enden. Jeg tror, at jeg begynder at få håb.\n\nFerauu og hans skiderikker kan komme når som helst. Vi har kun tilbage at gå ud og møde dem. Hvad siger du, vil du se det til ende med mig?", p="Hvis du formår at bringe mig nok banditmasker, så syr jeg måske nogle sammen og giver dem til Ferauu.\n\n<Aamelia griner højlydt.>"},
  [92693] = {c="Jeg... kan ikke tro, at det er slut. Jeg må standse op og falde til ro, før mit hjerte springer ud af brystet.", p="Der er ikke nok stormæbler i Himmelmuren til at betale dig for det."},
  [92698] = {c="Den konstruktion? Den har vandret rundt på markerne i årtier. Siden vindelementalerne forlod os, tror jeg. Alvarion mistænkte, at den engang bragte høsten til markedet, eller måske passede dyrene, før det var en frugthave. Det kan have været tusind år siden.\n\nI gamle dage plejede Vindformerne at vedligeholde disse konstruktioner. Vi talte om at bede dem om at komme og kigge på den, men det har aldrig været et presserende problem for os. I dag ignorerer vi den bare mest."},
  [92699] = {c="Velkommen, og vær hjertelig velkommen. Rattiril sendte mig en magisk besked om dig og nævnte, at du har potentiale.\n\nNu hvor du står foran mig, forstår jeg, hvorfor han foreslog, at du skulle søge mig. Du har en levende arkanistisk aura. Der er for få af os tilbage med anlæg, endsige vilje til at gøre det nødvendige for at redde vores hjem. Har du modet og styrken til at hjælpe Højordenen?\n\nVi finder ud af det."},
  [92700] = {c="Den Ældste Rafvind har sendt mig besked om dig og dine bedrifter i Shen'dar-landsbyen. Du er meget velset her, ven.\n\nDu har en stærk aura, og du har tydeligvis resonans med ånderne. Færre og færre af os har Himmelsyn, og Vindras har brug for dem med gaven, hvis vi skal overleve disse svære tider. Jeg er glad for, at du fandt vej til mig.\n\nJeg ser frem til at lære dig bedre at kende."},
  [92701] = {c="<Valennias ansigtsudtryk mørkner, mens hun læser brevet.>\n\nAonda stolede på dig til at levere det, og hun taler så højt om dig i dette brev, at jeg vil forsøge at stole på dig. Før vi taler videre, må jeg konsultere de få fredsbevarere, der er tilbage, og lægge en plan for, hvad der sker, hvis kulten angriber her næste gang. Nyd indtil videre opholdet i Valanår.\n\nHvis du leder efter noget at tage dig til, er der mange byfolk, der sikkert kan bruge hjælp fra en stærk ung eventyrer som dig.", p="Brev fra Aonda. Hvad har den snedige bjergjæger mon lavet?"},
  [92703] = {c="<Alvarions øjne fyldes med tårer, da du er færdig med at fortælle historien om, hvad der skete i frugthaven.>\n\nJeg ved ikke, hvordan jeg skal takke dig, ven. Jeg kom til Valanår og ledte efter håb. Elendigt håb, var jeg næsten sikker på. Men i stedet fandt jeg en helt. En ægte helt, ligesom i historierne fra de gamle dage, før vi kom til Himmelmuren.\n\nJeg glemmer aldrig, hvad du gjorde for os, Orsen. Du vil altid være velkommen i Vindmark-hjemmet."},
  [92706] = {c="Endelig er det nogen, der har dræbt den! Ved du, hvor svært det er at få en besætning til at sejle, når alle i byen konstant råber \"Haj!\"?\n\nJeg kan lige så godt putte den uhyres finne i aftensuppen i dag, så jeg får det sidste ord.", p="Hvad kan jeg gøre for dig, YOUR_RACE7?"},
  [92708] = {c="Så nu kan du se det? Der findes en hel verden af viden og ubrugt potentiale hinsides Himmelmuren. Det vil aldrig holde op med at være vores hjem, men jeg er nået til den konklusion, at vejen til vores frelse ligger nedenunder. Vi må rejse til Azerot og skaffe os magt og midler til at redde Vindras-øen. Det er vejen.\n\nVil du have modet til at slutte dig til os, når tiden kommer?"},
  [92709] = {c="Så nu kan du se det? At genopdage vores forfædres gamle magi er nøglen til at låse op for Vindras-øens hemmeligheder og sikre vores fremtid, men for at redde vores hjem må vi genopdage det, vi har mistet gennem de tusinde år.\n\nAzerot er nøglen. Kirin Tårn vil vise os vejen.\n\nNår vi gør os klar til at drage af sted, bør du henvende dig til de andre medlemmer af Højordenen her i Valanår. De fleste af dem har opgaver, der kunne bruge hjælp fra en som dig for at blive færdige."},
  [92727] = {c="<Posen foran dig har flere spor af, hvad der ligner tørret blod på klappen. Mens du studerer pletten, bemærker du også, at klappen har et navn broderet på sig. Der står \"Fillion Flammebrise\".>"},
  [92741] = {c="Det er da en ganske pæn mængde klør, du har bragt mig. Jeg kan ikke vente med at grave i dem!\n\nTak for din tjeneste for Højordenen, YOUR_CLASS7.", p="Højordenen plejer ikke at hyre sig selv ud som simple fælderstillere og dyrebude, men når sådan en tjeneste kan føre til videnskabelig gevinst, er vi glade for at engagere os i offentlige velgerninger."},
  [92742] = {c="Tak. Lad mig se...", p="Har du samlet prøverne?"},
  [92744] = {c="Jeg ser... disse multer ser sunde ud, for nu. Men vi kan ikke være sorgløse.", p="Håber murlocerne ikke har givet dig for mange problemer?"},
  [92745] = {c="Godt gjort, Xeph. Men jeg frygter, at giftens kilde måske ligger et andet sted..."},
  [92747] = {c="Hvad er alt det her?", p="Har du fundet noget?"},
  [92748] = {c="Har du brug for noget sprængt i luften?"},
  [92749] = {c="Det er en fin begyndelse! Nu skal alt det her sættes sammen... og få lidt ekstra kraft...", p="Vis mig de sprængstoffer, Busk!"},
  [92751] = {c="Fremragende - det er detonatoren, vi har brug for!"},
  [92752] = {c="Jeg er glad for, at du er vendt tilbage, Busk."},
  [92753] = {c="Så du har fundet smedjen og placeret bomben... der er kun én ting tilbage at gøre."},
  [92834] = {c="Den Højere Orden er stolt af vores pragmatisme og logik, og logikken dikterer, at det at undgå konflikt og tab af liv er det mest fornuftige valg i de fleste situationer.\n\n<Elaadrin Glødøjes øjne begynder at lyse og knitre med arkan energi.>\n\n...dog har kulten taget vores forsigtighed for svaghed, og de er på ingen måde klar til at betale for denne fejl.", p="Et lederes kendetegn er evnen til at indrømme en fejl. Jeg er uenig med Vindformerne i mange sager, men de havde ret i at forkaste tanken om en fredelig konfrontation med Al'Aketh. Mit forsøg på at vælge den højere vej kostede en kær ven livet, og det er en fejl, jeg må leve med resten af mine dage."},
  [92840] = {c="Det ville ikke være mit valg at udgyde Vindformernes blod, men skylden for denne konflikt hviler helt på deres skuldre. Du blev sendt for roligt at indsamle information, og de valgte at gribe til vold.\n\nNyheden har allerede spredt sig, og Vindformerne ved, hvad der skete ved de stående sten. De ville ikke vove en gengældelse her i Valanår, men de vil bestemt ikke glemme.\n\nPuh, du har været en uvurderlig støtte for Højordenen. Jeg kan let se, hvad Rattiril så i dig.", p="Det er ofte svært for mig at se forskellen på Vindformerne og Al'Aketh, bortset fra at den ene er mere åbenlyst brutal end den anden. Lige så dogmatiske og slaver af deres vildfarne tro er de begge lige farlige, hvis de bliver efterladt alene.\n\nDerfor er vores mission så kritisk."},
  [92849] = {c="J... tak, fremmede. Jeg gik ad vejen tilbage til Valanår, da en enorm skygge pludselig dukkede op over mit hoved. Jeg vendte mig for at kigge og så et massivt, uhyggeligt dyr styrte ned fra himlen imod mig. Jeg forsøgte at flygte, men blev ramt af fuld kraft, og lyset gik ud.\n\nDet er nok sikkert at sige, at hvis du ikke var dukket op, ville jeg have været middagen for det dyr og dets unger."},
  [92850] = {c="Nå, jeg må indrømme, at jeg er enormt lettet over, at Filøn er vendt tilbage til os. Han har aldrig kunnet passe på sin omgivelser. Altid for vild i tankerne eller med næsen begravet i en bog.\n\nTak, YOUR_CLASS7.", p="Den dumme Filøn..."},
  [92860] = {c="Det gør mig ondt at høre om Belathan. Han var faktisk min fætter og en god magiker og tjener for Zefras. Vi skal hævne ham.\n\nDu virker ivrig efter at tilbyde hjælp med det samme. Kom, lad os tale videre om den nuværende situation."},
  [92871] = {c="Du virker ivrig efter at tilbyde hjælp med det samme. Kom, lad os snakke videre om den nuværende situation."},
  [92880] = {c="<Valennia ser tydeligt lettet ud, når du fortæller hende om status for det østlige vagttårn.>\n\nTak, vinde."},
  [92881] = {c="Jeg har en lille sag, der præcis kræver den slags hjælp, som en eventyrer som dig kan yde."},
  [92909] = {c="Tak! Jeg går i gang med at udtænke en flugtplan. I mellemtiden, tag det her!", p="Der er et rod derude, Tetto! Har du samlet de dele, jeg har brug for?"},
  [92911] = {c="Så er den klar, Rotten! Den skulle virke fint. Gå og prøv den!\n\n...Mig? Nej, jeg bliver her. Jeg begynder faktisk at føle mig hjemme her.", p="Hvordan går projektet, Rotten?"},
  [92947] = {c="Vi kæmpede hårdt for at komme så langt, men det er ikke enden endnu."},
  [93036] = {c="Hilsen, barn, mit navn er Sania Sølvstrøm, og jeg er yngre præstinde i Al'Aketh-ordenen. Vil du gerne høre mere om vores hersker, Vindherren Al'Akiry?\n\nDer er altid plads ved Vindherrens bord til de retskafne og de angrende."},
  [93065] = {c="Vi er så klar, som vi kan blive."},
  [93089] = {c="Jeg er glad for at høre, at vi har Den Højere Ældste af Skyggesangens velsignelse over vores ekspedition. Nu, hvor kulten er besejret og forberedelserne er gjort, tror jeg, tiden endelig er inde.\n\nAnsærem har arbejdet utrætteligt for at hjælpe os med at opstille en stabil skyskærer-transport mellem Dalarn By og Zefras-øen. Vi har lavet så mange prøveflyvninger, vi kunne, og nu er det tid til at sende forposten af sted."},
  [93090] = {c="Jeg er glad for at høre, at vi har Den Højere Ældste af Skyggesangens velsignelse over vores ekspedition. Nu, hvor kulten er besejret og forberedelserne er gjort, tror jeg, tiden endelig er inde.\n\nMuln har arbejdet utrætteligt for at hjælpe os med at opstille en stabil skyskærer-transport mellem Zefras-øen og stedet kaldet Mulgorr, hvor Jordens Ring har sit hjem. Vi har lavet prøveture, og nogle af vores folk venter allerede på den anden side."},
  [93159] = {c="...det er nogenlunde alt, jeg har at sige om emnet. Jeg var--øh--et andet sted, før jeg var her. Nu er jeg her, og jeg har mine venner og mine ting. T-ting, jeg har bygget, mener jeg. Det er nogenlunde alt, hvad jeg behøver. Jeg tror, det er alt, hvad jeg behøver, under alle omstændigheder.\n\nJeg må dog sige, at det er rart at tale med nogen, der vil tale tilbage. Skovånderne prøver, men de ender med at synge til mig. Det er på sin vis rart, men ikke helt en s-stimulerende samtale.", p="Det er en historie..."},
  [93160] = {c="Tak, fremmede! Du vil se, at de er lækre, når du har ristet dem!\n\nVær venlig at undskylde, det tager ikke lang tid at gøre klar.", p="Mmm, jeg tror, du kommer til at elske det, de laver af de agern!"},
  [93165] = {c="Godt gået. Det kan kun blive godt ved at udrydde kulten. Jeg håber, det sender et budskab om, at Nattekloen ikke skal tages let på, og at vores nag går dybt.\n\nJeg formoder, at du får meget at se til med kulten. Hvis du samler flere ører, så bring dem herhen.", p="Jeg vil ikke sove, før mine hugtænder har gennemboret halsen på hver eneste kultist på denne ø."},
  [93172] = {c="Tak, fremmede.", p="Vi kan kun håbe, at de stakkels ånder kan finde fred, når de er sluppet fri af dette sted."},
  [93176] = {c="De er bare vidunderlige! Se på de forben! Panserets farver på den dér! Og de kæbeklosser!\n\nJeg vidste ikke, at du var entomolog, men du har virkelig et skarpt øje.\n\nVær så venlig, tag den her. Jeg tror, at den ene har taget en særlig kærlighed til dig, og denne art har jeg allerede katalogiseret.\n\nNu må du undskylde, jeg må tilbage til forskningen. Du har givet mig en hel del at studere!", p="Jeg må dog indrømme, at intet slår spændingen ved at opdage nye eksemplarer. Jeg plejede at elske at rode rundt i al det mudder og snavs, men i dag får jeg sjældent lejlighed til det.\n\nPå en måde er min lille flok både en velsignelse og en forbandelse. Da de kræver så meget opmærksomhed, kan jeg ikke komme ud over sumpen."},
  [93225] = {c="De er smukke - jeg undervurderede kentaurernes kreativitet. Jeg ville aldrig have troet, at et folk så fyldt af brutalitet og grusomhed kunne sætte pris på historier skåret i træ.\n\nMåske kræver det mindre anstrengelse at sætte pris på noget end at lave det. Jeg siger det på en anden måde: Jeg havde aldrig troet, at kentaurerne var tålmodige nok til at udskære så mange historier i træ. Hvor får de dog træet fra?\n\nUnder alle omstændigheder, kom tilbage til mig, når du er klar til at levere forsendelsen.", p="Er du allerede tilbage med totemerne?"},
  [93317] = {c="Vindene velsigne mig, det kød ser fantastisk ud!\n\nTusind tak, YOUR_CLASS7.", p="Kødet fra Vindsangskrybleren er ret almindeligt her, men det var en slags delikatesse på øerne Ambolas og Sirokas. Der var en tid, hvor himmelstrømmene var åbne, og beboerne ville jage mig, hvis jeg tog til Stjernehjem eller Ny Eldre'naar.\n\nJeg har ikke været i stand til at besøge de steder i... tja... lang tid."},
  [93318] = {c="Hvis vi ikke allerede havde nok på tallerkenen med kulten og banditterne fra højderne, behøver vi ikke en gigantisk wuldren, der terroriserer vores borgere. Du har udrettet en stor gerning i dag. Som lovet, her er din belønning.", p="Jeg får brug for skabningens hoved som bevis for din bedrift."},
  [93319] = {c="Tak, YOUR_CLASS7. Det burde hjælpe os for nu. Hvis vi ikke snart kan få orden på forsyningsruterne, bliver nogle stjålne vindsten det mindste af vores problemer.", p="De tyve har sikkert brudt ind i vores lagre i månedsvis. Jeg har forsøgt at overtale Aonda til at samle et angrebshold, så vi en gang for alle kan rydde bandithulen, men hun ville ikke trække de få vagter, vi har, væk fra landsbyen. Med kultisterne i Falaath-landsbyen mod syd, der vokser i antal, kan jeg ikke bebrejde hende det."},
  [93320] = {c="Vi holder dem stangen for nu, men de har flere tal, og vores krigere begynder at blive trætte. Vi må gøre noget for at bryde stilstanden, og det hurtigt."},
  [93461] = {c="Har du allerede besøgt Rathiril? Fint. Der har været en del spænding mellem Den Høje Orden og Vindformerne på det seneste, men de holder tingene civiliserede her i Shen'dar. Nå, i det mindste i landsbyen. Det, der sker i vildmarken, bliver i vildmarken.\n\nNu da det er gjort, ser du ud som en, der kunne tænke sig at finde noget at gøre med sine hænder. Jeg har et par ting, der skal gøres, hvis du er klar til lidt arbejde?"},
  [93552] = {c="Tak mange gange for stenene. Som alfer har vi alle en dyb forbindelse til magien, og disse vindsten bliver stadig mere værdifulde, eftersom magien, der er pumpet ind i øen gennem de store ankerpiller, stadig svinder hen.\n\nVindstenene er ikke det eneste nyttige, du kan samle op fra jorden. Værsgo, tag en af disse lærebøger.", p="Hej dér, YOUR_CLASS7."},
  [93680] = {c="Nøglen til kloakkerne? Nå, heldigvis er det ikke mig, der skal bruge den.\n\nMen før det bliver sikkert at bruge den, må vi arbejde lidt mere.", p="Hvad fandt du? En oldgammel bog? En mystisk relikvie?"},
  [93735] = {c="<Riaanis ansigt er gemt under konstruktionens tunge pladepanser, mens hun forsøger at arbejde på mekanismerne nedenunder. Hun bemærker slet ikke din tilstedeværelse.>\n\nSkide storme, hvor er kernen?! Hvem fik den idé at fjerne Gyrovinden også? Det er et under, at konstruktionens vinde slet ikke er spredt!"},
  [93736] = {c="At håndtere disse essenser fylder mig med en følelse af... dybe bekymringer. Jeg kan næsten mærke en ond, klagende aura udstråle fra dem. Nok til at få mig til at besvime.\n\n<Endaria ryster let.>\n\nJeg har ikke lyst til at undersøge dem nærmere.", p="Vindskyggeskoven er et farligt sted. Nogle siger endda, at den er hjemsøgt. Jeg er ret sikker på, at jeg ikke tror på det, men jeg ved, at det ikke er et sted for svage hjerter eller de uforberedte."},
  [93737] = {c="Tak for at samle disse materialer. Jeg forestiller mig, at nogle af dem ikke var lette at skaffe.\n\nMed disse dele kan jeg genstarte konstruktionen. Herfra kan vi kun håbe, at dens hukommelse er intakt, og at den kan fortælle os, hvem der tog dens komponenter.", p="Jeg kan ikke forestille mig, hvorfor nogen ville stjæle disse komponenter fra denne konstruktion. Bortset fra gyroskopet har disse komponenter næsten ingen praktisk anvendelse. Selv gyroen ville være næsten ubrugelig uden for dens tilsigtede formål."},
  [93738] = {c="Meget interessant, så det var Den Højere Orden, der var ansvarlig for revnen i konstruktionen?\n\nJeg kender Belathan. Han er fætter til Valennia Stormnæve, og hans mor var faktisk en Vindformer. Det er skuffende, at han var involveret i det.\n\nJeg må tænke over det et øjeblik."},
  [93740] = {c="<Ayessa ser chokeret og fjern ud, mens du rækker hende amuletterne fra Vindstenen.>\n\nLad dig ikke bekymre dig om mig, Sødeste. I dag har været en... prøvende dag for mig. Tak for din tjeneste for Vindformerne.", p="Al'Aketh har hengivet sig til deres blodige fanatisme alt for længe. Dette er blot begyndelsen på den afregning, de står over for."},
  [93746] = {c="Vent, hvad?! Belathaan... er død?\n\n<Ajessa lytter, mens du giver din beretning om det, der skete.>\n\nDen Højere Orden mødtes med Al'Aketh for at tale om fred? Der er ingen fred med en kult, de er morderiske fanatikere. Hvad tænkte Ælaadrin på, da hun sendte Belathaan af sted for at tage sig af dem alene?\n\nLad dig ikke slå ud af det, Marabi. Det er ikke din skyld. Den Højere Ordens arrogance har skylden, endnu en gang. Du var bare på det forkerte sted på det forkerte tidspunkt."},
  [93791] = {c="Åh, du må være Laderotem? Dejligt at se unge magikere, der er ivrige efter at lære vores skikke og historie. Kom, så forklarer jeg dig de næste skridt i at lave din besværgelsesild."},
  [93797] = {c="Tak, Mildru. Jeg kan virkelig mærke den elementære energi i denne gren, der venter på at blive brugt af dem med gaven til det. Det bliver et perfekt besværgelsesbål.\n\nSang denne gren måske til dig? Det hænder ofte, at grenen vælger YOUR_CLASS7 og ikke omvendt.", p="For hvert år, der går i Vindras, ser vi færre og færre af dem, der har evnen til magi.\n\nJeg er glad for at se unge magikere som dig deltage i vores ældste traditioner, så vi kan holde vores historie og kultur levende og i god behold."},
  [93835] = {c="Jeg sendte nogle af vores øvrige magikere for at sikre, at Valennia og hendes styrker kunne slippe væk. Hun bør hvile sig nu i Højelder Skyggesangs residens.\n\nAnsærem måtte vende tilbage til Azeroth, men han og jeg drøftede de næste skridt for Den Højere Orden, før han tog af sted. Vi overlevede dagen, men Vindras er nu farligt sårbar, og vi må lægge planer for det, der kommer."},
  [93836] = {c="<Talanaanis Skyggesang lytter opmærksomt, mens du fortæller ham om det, der skete ved Al'Akirs tempel, og om Ajessas plan om at forlade Vindras-øen.>\n\nJeg må tænke videre over det, men set fra den lyse side har vi fået Lorthunya-kulten af vejen og frataget dem deres leder. Vores hjem er ikke blevet angrebet, og på de elementære guders tidslinje kan det vare år... ja, årtier, før Al'Akir finder det værd at rette sin opmærksomhed mod os.\n\nDer er meget at frygte, men også meget at fejre."},
  [93926] = {c="<Kroppen her er ret frisk, tydeligvis kun for nylig dræbt. Ud fra forbrændingerne og brandmærkerne på denne fredsvagts hud er det klart, at han blev dræbt af stormbeherskende besværgere fra kulten.>"},
  [93927] = {c="Så de er alle døde. Må stormene forbande de forbandede kultister!\n\nSelvom du formåede at fælde præsten og standse kultisterne ved tårnet, må jeg indrømme, at jeg nu er dobbelt bekymret over det, du sagde, de gjorde ved pylonen. Den enorme ophobning af vindsten dér fortæller mig, at de havde brug for enorm energi.\n\nJeg må overveje, hvad det endelige mål er her? At krænke pylonen, angribe landsbyen? Hvorfor?", p="Hvad er nyt fra Vestvagten?"},
  [93928] = {c="(Pladsholder) Tak!"},
  [93948] = {c="Jeg er meget ked af at høre, at min nevø er død. Tak, fordi du hentede det og kom forbi til mig.\n\nDet er ikke almindeligt, at så dygtige unge Stjernebørn kommer ned fra bjergene. Hvis du har brug for arbejde, så tal venligst med Valennia Stormnæve, kaptajnen for fredsvagterne her i Valanår. I disse tider har vi brug for al den hjælp, vi kan få.", p="Hvad er det, hvad har du til mig? Åh... åh nej."},
  [93949] = {c="Jeg er sikker på, at der er flere af den slags skabninger omkring Valanår, men hver forbandet Himmelspringer, vi knuser, gør byen en smule tryggere."},
  [93951] = {c="Det kan virke som en lidt forfængelig bagatel - at samle fjer til vores hår. Men selv i tider som disse må man glæde sig over små glæder, så længe man kan.\n\nHvis en ting, jeg laver, glæder nogen, anser jeg det for en god dag. Tak, fordi du bragte dem til mig og hjalp med at bringe en smule glæde til Vindras.", p="Hvilke smukke ting har du medbragt til mig?"},
  [93963] = {c="Ah, du er tilbage.\n\nJeg håber, dine eventyr har givet dig en fornemmelse af vores verdens omfang og under. Jeg ved, at det må virke overvældende, men hvis du skal hjælpe dit folk, må du være forberedt på alt, hvad der måtte komme din vej på Azerot.\n\nMens du venter på, at din orden falder til ro i Dalarn, foreslår jeg, at du retter opmærksomheden mod landene omkring Stormvind. Vestfald kan altid bruge stærke eventyrere, især hvis du vil hjælpe dem."},
  [94003] = {c="Du gjorde det, jeg ikke kunne, og genoprettede min families ære. For det vil jeg give dig en gave, som få i Vindras er værdige til at modtage. Jeg vil lære dig hemmelighederne bag Himmelbryder-forsvaret.\n\nDu får også brug for et skjold for at omsætte det, jeg lærer dig, i praksis. Vær så venlig, tag denne. Den er ikke meget nyttig for mig længere, nu hvor Bastionen Himmelbryder er vendt tilbage til mig.\n\nBanu'Adoraah, ven.", p="<Sina nikker kort til dig.>"},
  [94006] = {c="Så du vil slå ind på Klo-stien, barn? Meget godt. Lad os tale sammen."},
  [94007] = {c="Jeg er meget glad for, at du er kommet. Kom, lad os komme i gang."},
  [94013] = {c="Fremragende, Nåneriel! Du er en ret hurtig lærling. Nu hvor du kender det grundlæggende, kan jeg lære dig at knytte et varigt bånd til en dyrefølgesvend.\n\nGå ud med denne viden og blomstr. Vær den YOUR_CLASS7, Vindras-øen har brug for.", p="Du lærer det, Nåneriel, og en dag bliver du en stor YOUR_CLASS7."},
  [94050] = {c="En nybegynder YOUR_CLASS7, ser jeg. Ja, jeg kan give dig de færdigheder, du skal bruge til at træne og lede dit kæledyr. Du vil ikke blot kunne lære dit dyr nye evner, men også fodre det og genoplive det, hvis det falder i kamp.\n\nHusk, Gei, respekter altid balancen og lev med respekt for naturen omkring dig. Nu må du hellere af sted. Vi snakkes ved en anden gang."},
  [94215] = {c="<Du spilder ikke tiden på at tilbyde den vibrerende masse af Fri Bevægelses-eliksir, som der blev bedt om. Den synes enten ikke at være klar over din tilstedeværelse, eller også er den ude af stand til at tage imod genstanden.\n\nEn håndfuld mønter ligger spredt lige ved siden af kokonen. Du kan vælge at lade eliksiret blive der og tage mønterne til dig selv. Naturen vil nok tage sig af det selv, i så fald.>", p="<Du nærmer dig det rasende væsen, der tydeligt sidder fast i et spindelvæv, præcis dér, hvor det er markeret på kortet.>"},
  [94241] = {c="Åh, dit timing er perfekt!\n\nCallahan! Din nye skjorte er ankommet. Skynd dig og tag den på, så jeg endelig holder op med at høre om, hvor meget den kløer dig.\n\nOg til dig, YOUR_RACE7. Her er din betaling. Før du går herfra, bør du kigge på mine varer – nu hvor du har råd til det!", p="HVAD???"},
  [94369] = {c="<Talanaanis Skyggesang lytter opmærksomt, mens du fortæller ham om det, der skete ved Al'Akirs tempel, og om Ælaadrins plan om at forlade Vindras-øen.>\n\nJeg må tænke mere over det, men set fra den lyse side har vi fået Lorthunya-kulten af vejen og frataget dem deres leder. Vores hjem er ikke blevet angrebet endnu, og i betragtning af elementarguders tidsskala kan der gå mange år... ja, årtier, før Al'Akir finder det værd at rette sin opmærksomhed mod os.\n\nDer er meget at frygte nu, men også meget at glæde sig over."},
  [94373] = {c="Godt gjort, dreng. Du har vist din parathed. Jorden er grundlaget for alle ting. Styrke, udholdenhed, tålmodighed. Den vil beskytte dig, men kun hvis du viser den behørig respekt. Selv en sten kan flytte sig, hvis du krænker den. Lær dens veje at kende, så bliver du klogere end de fleste. Glem aldrig de hemmeligheder, den har delt med dig.\n\nJeg forbereder straks en sapdrikken til dig - tag imod den, så vandrer du på sandhedens sti.", p="Tålmodighed, min dreng, er jordens smukkeste dyd. Den har set bjerge smuldre og floder hugge dale - langsomt og stædigt, ligesom en sand YOUR_RACE7. Jorden kalder dig nu, for der koger uro op i horisonten. Vend tilbage som sejrherre, så er du et skridt tættere på det hele.\n\nAndre kan misunde din visdom, men det er deres byrde at bære."},
  [94374] = {c="Ah... Thordin... jorden byder dig velkommen, selv i dette frosne land. Bundet i krop og ånd skal du gå fremad og vide, at bjergene er din styrke, slettene din tålmodighed og verden din essens.\n\nFor at gennemføre denne ceremoni, stå ydmygt foran jorden. De andre elementer er ikke så rolige - de støder sammen og skriger. Lær deres dobbelte natur at kende, selv her blandt sne og sten."},
  [94375] = {c="Godt gjort! Husk dette - totemer er ikke blot tegn på din plads blandt shamanerne. De er redskaber, fokus for besværgelser bundet til sten, jord og andre elementer. Når du bliver klogere, vil mere magt åbne sig for dig. Instruktørerne vil vide, hvornår du er klar til mere. Men tag nu dette totem, og lad jorden tale gennem dig.", p="Ahh, du er tilbage. Hvis du har en sten, så betyder det, at bjerget valgte dig rigtigt. Jeg giver dig det totem, det lovede. Men hvis du kom tilbage med tomme hænder, så væk med dig! Stien er ikke for dem, der glemmer deres vej."},
  [94411] = {c="Direkte konflikt med vores brødre og søstre Stjernebørn svækker os som folk, men nogle gange må der tages fast handling for at forhindre en større tragedie.\n\nMagikerne fra Den Højere Orden har nul respekt for konsekvenserne af deres magiske manipulationer. Kræfterne, der binder vores ø, er skrøbelige og sårbare, og alt, der skal til, er én tankeløs handling for at ødelægge vores hjem."},
  [94413] = {c="Nogle gange har jeg svært ved at skelne den blinde fanatisme i Al'Aketh-kulten fra Vindformernes stædige nægtelse af at ændre sig.\n\nHvis de virkelig troede, at vindene ville lede os, burde de mærke, hvilken vej vinden blæser, og flyde med den i stedet for imod."},
  [94414] = {c="Tak, fordi du fandt et øjeblik til at dele det med mig. Jeg vil fortsat våge over lunden og tænke over vores hjemlands tilstand.", p="Min gave er enkel og almindelig. Jeg kan ikke kigge mellem verdenerne som dem, der er velsignet med Himmelsyn, og jeg kan heller ikke øse af magien fra ley-linjerne under Vindras som de andre. Men en gave forbliver en gave, og jeg er taknemmelig for at eje den.\n\nAt værdsætte det, man har, er nøglen til lykke. At længes efter det, man kunne have, eller det man har mistet, fører kun til fortvivlelse."},
  [94427] = {c="Du... er du YOUR_CLASS7? Vær venlig, gør mig ikke fortræd. J-jeg ved, at jeg ikke burde tigge. Jeg har ingen konflikt med dig eller din orden. Lad mig være, jeg beder dig!"},
  [94434] = {c="Det er meget venligt af dig, YOUR_CLASS7. Virkelig meget venligt.", p="Jeg håber ikke, det er for stort et besvær for dig, dejlige YOUR_CLASS7."},
  [94435] = {c="Du har klaret dig godt, Gibari. Det var en lille sag, men selv små tjenester som denne kan styrke vores bånd til Lyset.\n\nDen Mørke Frue og mange i hendes tjeneste har ingen tillid til os. Nogle sammensværger sig endda mod os, men deres skepsis og frygt møder vi med mod og retfærdighed. Vi vil vise dem, at vi er medlemmer af de Forladte, og at vi gerne gør vores del, stor eller lille, så vores folk igen kan blomstre.\n\nTag dette symbol, du får brug for det til det, der venter dig længere fremme."},
  [94440] = {p="Hvad er nyt fra Falgaards Dødsvogter?"},
  [94441] = {c="Livets Symbol kan kun bruges af en YOUR_CLASS7, der er parat til at modtage et af lysets største velsignelser. Jeg er stolt over at regne dig blandt os, og nu skænker jeg dig gaven om genløsning. Med den vil du kunne genoplive dine faldne kammerater. Brug denne nye velsignelse klogt.\n\nDu har gjort det godt for både de Forladte og korsridderne fra Tyrs Vagt. Hvert skridt vi kan tage for at vinde vores søskende de Forladtes hjerter og sind er et godt besvær værd. Gå i lysets vej, Anakrom."},
  [94449] = {c="Hmm... så det var den ældste, der sendte dig, hva'? Nå, YOUR_CLASS7s ord er solidt, så jeg vil ikke modsige. Det betyder, at du er klar til den næste sapdrik. Ild-sapdrikken. Jeg kan allerede se det i dit øje -- glød, sult. Du har smagt magten, og nu vil du have mere. Men husk dig selv, Skamfor. Husk hvad stenen lærte dig. Ild er let at manipulere, men sværere at tæmme. Vid hvornår du skal holde igen."},
  [94465] = {c="Ah, min undskyldning, Ret. Jeg bemærkede ikke fakkelen i din hånd. Ære at møde dig ordentligt.\n\nMange vandrere klatrer op i disse højder og jagter fortællinger om skatte eller bestier, kun for at finde intet andet end sten og stilhed. Men vi ved bedre, ikke sandt, Ret?\n\nDette tempel rummer sandheder dybere end noget, alliancen kan begribe. For os er det en hellig flamme, der venter på at blive genantændt.", p="Hilsen, Ret. Du er nået til Den Hvilende Flammes Tempel, hva'? Ikke mange gør det. Kun dem, der kender vejen som YOUR_CLASS7 godt, kan gribe stedets hemmeligheder.\n\nHvordan er du kommet helt hertil, bare for at blive sendt tilbage? Klatringen er ikke en spadseretur i Dun Frostbakke. Men jeg er templets vogter, og jeg vil ikke lade en almindelig rang ryste her."},
  [94466] = {c="De bliver perfekte, Ukke.\n\nIld er ikke kun raseri og ruin--husk mine ord. Det er liv, det er smedjen, det er skabelsens ånde. Alle ting er bundet sammen i balance. Den ene kraft tempererer den anden og giver den betydning. Uden skygge er lyset blot skarphed. Uden flamme er stenen blot en kold erindring.\n\nAt beherske magi betyder at vide, hvornår man skal blande, ikke kun brænde. Det er ægte visdom, min dreng.", p="Aye, jeg har næsten alt, hvad jeg skal bruge til et ildsaptak, Ukko - jeg mangler bare ildtjære og seerens pung. Tjæren bæres af Rottetunnel-geomanterne i dværgehulerne indtil midnat. Pungen må du presse ud af Madalbardc Splitteren i de sydlige bakker. Disse ingredienser er knyttet til ild, sådan skal alle ægte saptak være. Deres elementære bånd gør vores fremstil kraftfuld."},
  [94467] = {c="En hvid, varm flamme tænder sig i skålen, når du lægger kul i. Du kan mærke saptakens magiske virkninger strømme gennem din krop, og ilden danser rytmisk foran dig.\n\nDu sætter fakkelens top i bassinet, og den antænder straks. Røgen synes at drive hen mod Sortklippebjerget.", p="Ildskålen står en tredjedel af din højde, med forkullede udsmykninger langs dens glatte metalskinner. Metallet viser ingen tegn på vejrslid, og skålen øverst føles kølig at røre ved.\n\nSortklippebjerget tårner sig op i det fjerne med klar udsigt, så det kan hylde fra dette hellige sted."},
  [94468] = {c="Ved Madorans skæg, din ånd brænder klarere end nogen fakkel, jeg nogensinde har set, Ret - og det er noget at være stolt af.\n\nBliv ved med at gå ad denne vej, og elementerne vil bøje sig efter din vilje. Vores folk vil komme til dig for visdom og vejledning. Så lad mig være den første til at tilbyde mine hjertelige lykønskninger - og præsentere dig for dit nyeste totem. Du har fortjent det, flammesvedne.", p="Aye, Ret? Hvad har du dér?"},
  [94484] = {c="Gud være lovet, at vores budskab nåede Lotheluum. Vent, hvor er resten af forstærkningerne? De sendte vel ikke dig alene?\n\n<Elegæl bleger, når du genfortæller din samtale med Lotheluum.>\n\nSå budskabet nåede ikke frem. Vi befandt os i en nødsituation dengang.\n\nDet ser ud til, at vi må klare os selv. Tiden er afgørende."},
  [94485] = {c="<Elegael tager den klistrede bunke mos fra dig med et svagt smil.>\n\nTak, Trogdorp, du har gjort det godt. Det er præcis, hvad vi har brug for.", p="Har du fundet Frues Tårer?"},
  [94486] = {c="Tak for disse. Jeg skal sørge for at bruge hver eneste fjer, så deres offer ikke bliver forgæves.", p="Det gør mig ondt at bede dig om at dræbe de unge shrieklings, men med deres voksende fjendtlighed på det seneste er det til det bedste. Vi kan kun klare så mange trusler ad gangen."},
  [94487] = {c="<Elegael kigger bekymret ned på de blodige minder, han samler op.>\n\nSå mange unge liv med så stort potentiale er nu væk for altid. Tak for at bringe disse tilbage, YOUR_CLASS7.\n\nJeg vil opbevare dem sikkert, indtil jeg kan tage dem med til Den Høje Ældste. Der kan de vende tilbage til samlingen og vente på en næste, og måske mere værdig, generation til at træde ind i voksenlivet.", p="Jeg skal få kulten til at betale for hver eneste dråbe druideblod, de har udgydt i dag."},
  [94488] = {c="<Elegael rynker panden ad det afhuggede hoved, men nikker kort.>\n\nTak, Thaildras. Uanset hvor meget raseri jeg har indeni, ville det være svært at slå min egen fætter.\n\nGræd ikke over ham. Hans uvidenhed og vrede dræbte mange uskyldige i dag.", p="Er vores brødres liv virkelig så lidt værd for dig, Haalien?"},
  [94489] = {c="<Elegaels ansigt blegner, når du fortæller om Jorls skæbne og de resterende druiders tilstand.>\n\nNej... nej! Det er langt værre end mig--\n\n<Elegael hulker tilbage, skærer tænder og lader sig selv udstøde et smertefuldt skrig.>\n\nDe skal betale. De skal ALLE betale. Enhver, der allierer sig med Al'akett, vil mærke min vrede! Det sværger jeg.", p="YOUR_CLASS7! Du er tilbage. Var du i stand til at nå min bror og søster? Fandt du Jorel?"},
  [94490] = {c="Er de kommet hertil som bønder? Men hvorfor? Var vi ikke det oprindelige mål for deres angreb?\n\n<Elegæl afbryder, rystende af raseri, mens beskeden læses.>\n\nDe dræbte mit folk, fordi vi var en byrde! Jeg river hver kultist i stykker med mine hugtænder! Jeg sørger for, at ingen herfra kommer levende ud.\n\nSkynd dig! Hvis ordrerne virkelig kommer fra Valanår, så betyder det, at der gemmer sig en forræder et sted. Giv Lotheluum i Valanår besked og fortæl ham, hvad der er sket."},
  [94491] = {c="<Lotheluum har et oprigtigt forfærdet udtryk i ansigtet, mens hun fortæller om hændelserne i YOUR_CLASS7's hule.>\n\nJa—undskyld, Solarus. Jeg har bare brug for et øjeblik. Jeg har ingen ord til at beskrive dette tab.\n\nDette er meget alvorlige nyheder. Hvis budskabet ikke er falsk, har vi her i Valanår enten fået den bedste medarbejder eller den værste forræder. Jeg tager det med til Den Ældste med det samme! Jeg vil ikke lade mine kammeraters offer gå til spilde."},
  [94568] = {c="Vi kunne prøve at sende vagterne ud for at angribe kultisternes styrker direkte, men vi ville ikke have en chance mod dem i åbent slag.\n\nVi får brug for en anden tilgang.", p="Denne flygtning risikerede alt for at undgå kulten og bringe os denne krystal..."},
  [94638] = {c="Smerten, jeg føler over hendes tab, er umålelig, men den er nødvendig for balancen. Du har vist beslutsomhed til at holde ud, selv når den forfærdelige pris bliver nævnt.\n\nDu har klaret dig godt, YOUR_CLASS7. Jeg vil give dig en velsignelse til at antage formen af min slægtskab. Vær en lygte for dem, der mangler styrke til at holde ud, og en forsvarer for dem, der har brug for det.\n\nGå nu og tag klovens vej, barn."},
  [94774] = {c="Jeg er glad for, at du er kommet, Ander. Der er mange ting, vi må drøfte, men vigtigst af alt er din oplæring på Lysets veje.\n\nDer er lektioner, alle der tjener Lyset må lære. Hvis du er klar, begynder vi at gennemgå nogle af dem nu."},
  [94789] = {c="Godt, jeg giver dig det, du behøver for at samle vindbesværgelser og kalde luftens ånder. Tag denne totem, og når du er klar, så træn lidt mere med mig."},
  [94824] = {c="Du har været længe om at komme hertil, Papi. Men vi kan tilgive dig, al den tid du har viet Lysets tjeneste. Vær venlig at give særlig agt på denne lektion."},
  [94896] = {c="Tak, YOUR_CLASS7, du har vist os flygtninge stor venlighed i dag. Jeg vil sørge for, at disse ting når frem til deres ejere. Det giver os i det mindste en begyndelse på en ny start.", p="Mange af os forlod med kun tøjet på kroppen. Enhver ting, vi får tilbage, ville være uvurderlig."},
  [94897] = {c="<Ealånes øjne fyldes med tårer.>\n\nÅh, Resaan, min kærlighed. Hvad skal der nu ske med os? Der var så meget... jeg føler, som om vores liv sammen netop er begyndt.\n\nTak, YOUR_CLASS7. Verden er grusom, når den tager både mit hjem og min kærlighed fra mig. I det mindste vil hans minde give mig en vis trøst.", p="Hørt noget om Resaan? Å, YOUR_CLASS7, ventetiden er hård efter alt det, der er sket."},
  [94911] = {c="En højelv, der taler til mig... i Tordenklippe. Vil underne aldrig ophøre?\n\nNå, vindskabning, lad mig slutte mig til vores brødre og søstre i Jordringen og byde dig velkommen til Azeroth. Mine druide-brødre fra Cenarion-kredsen har masser af visdom at give dig, naturens barn."},
  [94913] = {c="Ah, jeg ser, at du allerede har mestret Bjørneformen. Godt, godt. Du er godt på vej, unge YOUR_CLASS7."},
  [94946] = {c="Ah, du er nået frem. Fremragende. Det tager os lidt tid at slå os ned her, så du vil måske gerne bruge noget tid på at udforske byen. Vær dog forsigtig, og prøv ikke at gå for langt væk fra byens sikkerhed.\n\nSelvom dette nye land virker som et paradis, kan det være yderst farligt at vandre uden for Dalarn uden ordentlig forberedelse og erfaring."},
  [94947] = {c="Hilsen, YOUR_CLASS7. Jeg er Bolvar Fordrågon, tronregent af Stormvind.\n\nBudbringeren fra Kirin Tårn sagde til mig, at jeg skulle vente en udsending fra Højordenen, og så står du her. Der er gået lang tid, siden en højelver stod i denne tronsal, men jeg er glad for at byde dig velkommen som gæst.\n\nPå Kongens vegne byder jeg dig velkommen til Stormvind og giver dig tilladelse til frit at rejse gennem Alliancens lande. Velkommen til Azerot, Himmelbåren."},
  [94978] = {c="Godt tæmmet, Jægeren! Du tilegner dig allerede færdigheder.", p="Du vil lære, Venator, og en dag bliver du en stor YOUR_CLASS7."},
  [94979] = {c="Er du allerede tilbage! Imponerende tempo, Nåneriel!", p="Du vil lære, Naanariel, og en dag bliver du en stor YOUR_CLASS7."},
  [95034] = {c="Nu forstår du. I hans sidste kræfter, efter at han var gennemboret af et dusin gnoll-klinger, rejste han sig for at angribe mig. I det sidste øjeblik så vi hinanden i øjnene, og jeg kunne se, at han stadig vidste, hvem han var, og at han genkendte mig. Han vidste, hvad der skete, men han havde ingen kontrol over sig selv. Det var den værste del.\n\nHvis det er muligt, vil jeg finde det uhyre, der dømte ham til døden, så det aldrig igen besøger denne rædsel på et andet levende væsen. Det sværger jeg ved himlen over os."},
  [95036] = {c="Nu da vi har de nødvendige materialer, skal vi bare finde nogen, der er værdig til at smede våben for os. Jeg tror, jeg kender lige præcis sådan en håndværker.", p="Stol på lyset, så det leder dit våben. Men lyset har dog også brug for et godt våben for at kunne lede."},
  [95041] = {c="Disse kort virker lidt fugtige... men jeg klarer det! Tak, Arkenatum!", p="Hvordan skrider datagendannelsen frem?"},
  [95065] = {c="Perfekt timing! Jeg fangede en stor fisk på mine sidste agn. Vidunderlig dag indtil nu. Her bider de virkelig!\n\nHør nu, eftersom du har været så venlig og holdt en gammel mand i forretningen, hvad med et par fisk til vejen?", p="Har du allerede skaffet fiskeudstyret?"},
  [95161] = {c="Åh nej...\n\nDet er venligt af dig at bringe det, men jeg tror ikke, Jeremy er klar til at se det. Matrone Nattergal sagde, at min lille Jeremy ikke har talt siden angrebet på Herrelande, og jeg har ikke tænkt mig at tvinge ham til det. At vise ham det vil bare give ham mere smerte.\n\nSe ikke sådan på mig. Jeg vil ikke skjule hans fortid, men han har brug for tid til at hele. Jeg giver ham det, når han er blevet ældre. Tak for besøget, men jeg synes, du skal gå nu.", p="Hva'? Hvad drejer det sig om?"},
  [95195] = {c="Din intuition om at bringe dem til mig var ikke ubegrundet. Da Herrelande faldt for pesten, flygtede mange mennesker for at finde ly her i Stormvind. Der er nok kun få tilbage, som selv kan hente de her insignier.\n\nDin tjeneste for Stormvind bliver rost, Sort. Jeg begynder straks at uddele disse mærker til de nærmeste pårørende.", p="Du ser ud, som om du bærer på en tung byrde, Sort. Hvad er det?"},
  [95204] = {c="<Orla bider i urten for at tjekke, om den er ægte.>\n\nNå, se lige her. En ægte oldsag fra vores hjem. For det meste uskadt, faktisk. Vi må være ekstra forsigtige med den.\n\nTak for din hjælp med at genoprette vores historie, YOUR_CLASS7. Jeg skal passe godt på den.", p="Hvad har du dér, YOUR_CLASS7? En lækker lille bid?"},
  [95212] = {c="Disse skind bliver fine sadler. Du har vundet ære for Alliancen, YOUR_CLASS7!", p="Du ser frossen ud, YOUR_CLASS7. Hvordan går jagten?"},
  [95213] = {c="<YOUR_RACE7 bliver bleg ved synet af den tomme tromme.>\n\n...Hvor fandt vi den?", p="Hvad har du dér?"},
  [95214] = {c="Det burde være alt det stjålne pulver. Tak, YOUR_CLASS7.\n\nVær så venlig at tage denne belønning, og... jeg ville ønske, du ikke ville nævne denne lille hændelse for nogen.", p="Jeg håber, du har gode nyheder til mig?"},
  [95216] = {c="Dræbte du ham??\n\nHmph. Heldigvis burde der være nok ichor til at genskabe hans egenskaber. Du vil ikke være en fjende af Det Kongelige Apotekerselskab.\n\nSkrid!", p="Enhver tosse vil fortælle dig, at den mest effektive transmissionsmetode altid går gennem blod.\n\nJeg må se det med mine egne øjne!"},
  [95314] = {c="Siger du, at der er ondskab i Skyggedalen? Jeg må indrømme, at jeg ikke er overrasket. Folkene fra skoven var mærkelige og kunne ikke lide besøgende. Nogle tror, at selve Hviskeskoven er forbandet, og eliksiret destilleret af dens rødder bærer den samme forbandelse...\n\n...men nok med overtro og sladder, Hm. Tak for eliksirerne. Her, tag det som betaling.", p="Jeg håber, du ikke er faret vild?"},
  [95328] = {c="Et interessant eksemplar. Fra Hviskeskoven, siger du? Det er ingen hemmelighed, at det forfærdelige sted er plaget af tomrummet.\n\nJeg glæder mig til at undersøge skyggens hemmeligheder, YOUR_CLASS7. Lad mig tilbyde dig en betaling for det, du har fundet.", p="Har du noget til mig, YOUR_CLASS7?"},
  [95349] = {c="Flere eventyrere fra Vindras, ser jeg. Storartet. Vindene er helt sikkert med os! Det vil tage os et stykke tid at komme på plads her, så du vil måske bruge noget tid på at udforske denne nye jord.\n\nAzerot er en spændende ny verden, men det er også en farlig verden. Det ville være godt at forberede sig på dette nye eventyr ved at sætte sig ind i de nærliggende lande."},
  [95350] = {c="Lokk-tar, YOUR_CLASS7. Jeg er Trael, Hordens Krigshøvding.\n\nBudbringeren fra Jordringen fortalte mig, at jeg skulle vente en udsending fra Vindløberne, og her er du så. Jeg havde ikke forventet at se en højelf stå foran mig her i Orgrimgrad, men Hordens skal byde dig velkommen som vores gæst.\n\nDu har min velsignelse til at rejse gennem Hordens lande. Drag afsted med ære, Vindløber."},
  [95494] = {c="Ja, de skind bliver rigtig gode. Jeg har en aftale med den lokale pukkelryg om at levere de rå skind i bytte for diverse færdige lædervarer, som jeg bruger som en del af min handel.\n\nJeg har aldrig manglet min aftale til sidst, og selv med mit sår har jeg ikke tænkt mig at ændre det.", p="Hvordan går jagten?"},
  [95507] = {c="Tak for din hjælp, YOUR_CLASS7. Jeg var ved at undre mig over, om jeg bliver nødt til at gå sulten i seng på grund af denne forbandede benskade.", p="<Skæv harker højlydt op, når du nærmer dig.>"},
  [95621] = {c="Så de leder efter en desertør... Nå, det ser ud til, at fortiden endelig har indhentet mig.", p="Resterne af Daelin Stoltmoors flåde, som stadig bærer hans banner, er lige så råddne og barbariske, som admiralen selv var, før han døde.\n\nJeg ved ikke, hvorfor de er så langt fra Tiragarde, men det kan ikke være godt."},
  [95646] = {c="Det er værre, end man kunne have forventet. Den gamle energi vågner. Det er klogest, hvis du fortæller dine ivrige gravere at holde op med at grave, for deres egen sikkerheds skyld.", p="Disse vande gemmer et mærkeligt liv i saltlagen, der lige så gerne giver, som de tager."},
  [95663] = {c="Er det de modige få? Vær forsigtige med jeres ord."},
  [95664] = {c="Det er et godt tegn, at fremmede kommer på den måde. Jeg kan mærke kraft i dig... hvad er det, du har med dig?", p="Åndene viser dig ære. Er du kommet for at dele med os?"},
  [95682] = {c="Gør dig ikke noget over, at jeg river det ud af hænderne på dig.\n\nJeg genkendte den orkiske kradseri. Så de håber at blidgøre Flænse? Forgæves og spildt anstrengelse.\n\nAltså, det gør ikke noget, det er yderst værdifuld viden for Den Mørke Frue.\n\nJeg tager det ikke med mig. Og tal ikke om missionen, menig.", p="Vi er her for at udføre en vigtig opgave. Hvis du kan hjælpe, så bevis det."},
  [95697] = {c="Se den marmorering! Hvad spiser de dog deroppe? Tak, fordi du gik hele vejen derud og tilbage. Hvis du ikke har noget imod at vente, laver vi det til dig nu, helt gratis selvfølgelig!", p="Avlet vildsvin, avlet krebsdyr... hvad er det næste, avlet rovfugl?"},
  [95737] = {c="Llana undrer sig sikkert over, hvor de græsfrø er, som jeg lovede, at min mand ville bringe hjem! Det trøster mig, at hun bekymrer sig lige så meget som jeg. Det må have noget at gøre med selve udgravningen, for vi fornemmer begge det."},
  [95774] = {c="Jeg vil placere disse pynteting ved mindesmærket for min kone, så jeg aldrig glemmer hende. Mit blod vil altid være hedt af lyst til hævn!\n\nDu har vist mig... vist os... en stor tjeneste, Johannes.", p="Jeg har kun minderne tilbage, men jeg vil bygge en hyldest til Olgra, så de aldrig forsvinder."},
  [95795] = {c="Åh, nej...\n<Skjuler ansigtet i hænderne og hulker.>\n\nJeg burde have taget med dem.\n\nMeget af det, jeg smedede, var til ham. Jeg planlagde en overraskelse, men den var ikke klar, da han kom for at hente rejsesagerne.\n\nNu hvor de er færdige, har jeg ikke hjertet til at ændre dem eller sælge dem.\nTag dem. Det mindste, jeg kan gøre for dig, efter at du har bragt mig denne dystre dag."},
  [95803] = {c="Jeg tvivler ikke på Danithas oprigtighed eller hendes lyst til at skaffe jeres slags en plads blandt de Forladte. Men jeg mistænker, at det ikke er sidste gang, en af jeres brødre eller søstre bliver gal og vender lyset mod sit eget folk.\n\nDer kan komme en tid, hvor jeg beslutter, at det ikke længere er i de Forladtes bedste interesse at tolerere jeres fordømte orden. Jeg foreslår, at du fortsat tjener dit folk med hengivenhed.\n\nVi holder øje.", p="Hvorfor henvender du dig til mig, YOUR_CLASS7?"},
  [95809] = {c="Gode gud, det lyder skrækkeligt!\n\nLyset være med mig, jeg er glad for, at han er en af de overlevende.\n\n<Holder et flettet rørhjerte op mod sit eget.>\n\nJeg begynder at lave et rigeligt måltid til ham. Tak, fordi du bragte mig dette. Jeg vil gerne have, at du tager imod noget som tegn på vores taknemmelighed.", p="Det er ham, jeg er mest bekymret for!"},
  [95810] = {c="Ak, du har vovet dig helt herud og overlevet for at fortælle om det?! Lad os se, hvad du har med dig.\n\nTja, når jeg ved, hvad du har været igennem for at bringe mig det, mener jeg, at din artefakt fortjener en vis respekt.", p="Er du kommet for at grave?"},
  [95883] = {c="<Den forbandede sjæl udsender en modbydelig energi i nærheden af offersten.\n\nDet ser ud til, at du er tættere på at fuldføre ritualet.>", p="<Røgelsesrøg stiger ondskabsfuldt op mod himlen.>"},
  [95884] = {c="<Mærkelige redskaber og genstande ligger spredt ud over den ru stenoverflade.\n\nDet er bestemt offerstenen, som omtalt i noten.>"},
  [95885] = {c="<Offerstenen er nu livløs. Det ser ud til, at dit ritual har tømt den for kraft. Til hvilket formål, ved du ikke, men det hele er slut.\n\nDen ru sten revner og smuldrer, nu berøvet sit formål.\n\nNoget blinker fra resterne...>", p="<Offerstenen er ondskabsfuldt ubevægelig.>"},
  [95981] = {c="Siden barrieren omkring Dalarn faldt, har Kirin Tårn holdt et dødeligt greb om vejene. Noget bekymrer dem, det er sikkert.\n\nMen for nu er årsagen uvæsentlig."},
  [95998] = {c="Nu da vi har lært det grundlæggende, hvorfor tager du så ikke hen og lærer håndværket. De lærer dig også viden om at bygge den rette lejrgenstand, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve ved hoffet, er afgørende. En veludhvilet og veloplagt eventyrer har langt bedre chancer for at overleve i denne livsstil."},
  [95999] = {c="Godt arbejde, Erajna! Forbrænder Gar'im forberedte sig på at styrke forsvaret af Stenvagtsfæstningen. Med denne sejr kan vi stadig lykkes med at generobre fæstningen!", p="Hvad har du dér, YOUR_RACE7?"},
  [96031] = {c="Værsgo, dit helt eget campingtelt. De fleste gider ikke slå telt op midt i byen, så du bliver nødt til at tage ud i den vilde natur, hvis du vil teste det.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære at lave ild. Hvis du ikke har gjort det endnu, kan du måske finde en, der kan træne dig i madlavningens kunst, så du lærer det basale."},
  [96044] = {c="Der har du det, nu kan du lave din helt egen Slibesten. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96045] = {c="Der har du det, nu kan du lave din helt egen Manabrønd. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96046] = {c="Der har du det, nu kan du lave din helt egen Magnetsten. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende.", p="Ja, jeg kan lære dig det."},
  [96047] = {c="Der har du det, nu kan du lave dit helt eget Førstehjælpssæt. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste det.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96050] = {c="Der har du det, nu kan du lave din helt egen Fiskeskål. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96055] = {c="Der har du det, nu kan du lave dit helt eget Røgelsesstearinlys. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste det.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96056] = {c="Der har du det, nu kan du lave din helt egen Lejrstol. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96057] = {c="Der har du det, nu kan du lave dit helt eget Indsamlingsbanner. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste det.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96059] = {c="Der har du det, nu kan du lave din helt egen Fortryllet Lut. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende.", p="Ja, jeg kan lære dig det."},
  [96101] = {c="Nu da vi har lært det grundlæggende, hvorfor tager du så ikke hen og lærer håndværket af trænerne i den nærliggende landsby. De lærer dig også, hvordan du bygger en lejrgenstand, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve ved hoffet, er afgørende. En veludhvilet og veloplagt eventyrer har langt bedre chancer for at overleve i denne livsstil."},
  [96102] = {c="Der har du det, nu kan du lave dit helt eget Indsamlingsbanner. De fleste bryder sig ikke om lejre slået op midt i byen, så du må ud i vildmarken, hvis du vil teste det.\n\nÅh, og husk nu, ingen lejr er komplet uden et bål. Du bliver nødt til at have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [96139] = {c="Denne bog ser ud til at være historien om Tapper-familien. Jeg tror, jeg har hørt om nogle af dem. Gode folk. Jeg er ikke sikker på, at de fortjener en hel bog om sig selv.\n\nJeg laver en kopi af bogen til dig. Hvis du ser noget andet, der har med dem at gøre på dine rejser, tager jeg gerne imod det.", p="Har du fundet noget endnu? Jeg regner ikke rigtig med det."},
  [96241] = {c="Heh... da jeg talte om de særlige egenskaber, lavede jeg ikke sjov, makker! Du ser ikke værre ud, så alt er i orden.\n\nTak for hjælpen, YOUR_CLASS7. Det sætter jeg stor pris på.", p="Har du allerede det, jeg har brug for?"},
  [96259] = {c="Tak for din tjeneste for folket i dette land. Det kan tage tid at rydde området for denne invasion, men dine bestræbelser har givet os et stabilt brohoved, som vi kan bruge mod de onde skabninger."},
  [96260] = {c="Det er fremragende prøver, de er rigeligt til mine formål.\n\nVær så venlig, tag den her. Jeg har formået at fremstille en usædvanlig kappe af stof vævet af en lille prøve silke, som jeg allerede har. Jeg håber, den kommer dig til gode på rejsen.\n\nMå Jordmoderen våge over dig, YOUR_CLASS7.", p="Denne silke har usædvanlige egenskaber og kunne bruges til at lave et let, holdbart stof med fremragende forsvarsegenskaber. Jeg eksperimenterer gerne med mere af den."},
  [96261] = {c="Genoplivede lig? En yngelmoder i færd med at antage en natteelvs skikkelse? Det er urovækkende fund. Jeg funderer over, hvad det hele betyder... Jeg frygter, at det er et problem til en anden gang.\n\nTak, YOUR_NAME. Du har gjort Jordens Kreds og Mulgorrs folk en stor tjeneste."},
  [96294] = {c="Det... er meget urovækkende. Hvorfor ville en druide stå bag en sværm af farlige edderkopper? Hvem eller hvad er denne \"Vilde Konge\" og \"Pagten\", som brevet nævner?\n\nJeg vil søge råd hos druiderne fra Cenarius-kredsen om den sag. Måske ved de mere.\n\nTak endnu en gang for hjælpen. Selvom oplysningerne er skræmmende, er det mere beroligende at vide, at den, der styrede de nederdrægtige skabninger, er blevet fældet.", p="Hvad er det?"},
  [96390] = {c="Disse Mørkjern-dværge kan være vores fætre, men de er bestemt ikke vores familie. Jeg vil ikke fælde en tåre over de ulykker, der rammer dem, som vandrer for langt fra det forbandede bjerg.\n\nJeg håber, det er nok til at skræmme dem fra at lave flere angreb på disse lande."},
  [96391] = {c="Ud fra dette kort ser det helt bestemt ud til, at de Mørkjernerne planlægger en slags togt mod skatkamrene under Jernsmede. Banden, du knuste mod øst, må have været en spejderstyrke.\n\nTak, fordi du bragte mig dette. Skynder vi os, kan vi komme dem i forkøbet dernede under.", p="Åh, hvad er det så?"},
  [96392] = {c="Så nu ser du det, YOUR_CLASS7? De er talrige som kakerlakker, og det er kun dem, vi kan se fra himlen.\n\nDu ser solid nok ud. Har du lyst til lidt vold?", p="Fjernblik kan vise dig mange ting, selv ting du helst ikke havde set."},
  [96394] = {c="Ah, det er klaret. Jeg kan ikke have, at andre vagter nægter adgang til salen for at udføre deres pligter på grund af \"ånder\" og \"rasende de døde\", kan jeg?"},
  [96403] = {c="Se dig selv, du er lige så modig, som du er driftig! Jeg, en gnome af ord, og din belønning er velfortjent!\n\nNu lad mig se på byttet - øh, jeg mener... de genvundne familiearvestykker. Jeg må i gang med vurderingen - undskyld, 'katalogiseringen' af dem, så de hurtigt kan komme tilbage til deres rette steder.", p="<Tom gnider sig ubevidst i hænderne, mens han kigger på dig.>"},
  [96408] = {c="Hilsen, ven. Hvordan har du det?"},
  [96604] = {c="Nu da vi har styr på det grundlæggende, hvorfor tager du så ikke hen og lærer erhvervet af trænerne i den nærliggende landsby. De lærer dig også, hvordan man laver et lejrudstyr, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve under åben himmel, er afgørende. En veludhvilet og veloplagt eventyrer har langt større chance for at overleve denne livsstil."},
  [96605] = {c="Nu da vi har styr på det grundlæggende, hvorfor tager du så ikke hen og lærer erhvervet af trænerne i den nærliggende landsby. De lærer dig også, hvordan man laver et lejrudstyr, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve under åben himmel, er afgørende. En veludhvilet og veloplagt eventyrer har langt større chance for at overleve denne livsstil."},
  [96606] = {c="Nu da vi har styr på det grundlæggende, hvorfor tager du så ikke hen og lærer erhvervet af trænerne i den nærliggende landsby. De lærer dig også, hvordan man laver et lejrudstyr, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve under åben himmel, er afgørende. En veludhvilet og veloplagt eventyrer har langt større chance for at overleve denne livsstil."},
  [96607] = {c="Nu da vi har styr på det grundlæggende, hvorfor tager du så ikke hen og lærer erhvervet af trænerne i den nærliggende landsby. De lærer dig også, hvordan man laver et lejrudstyr, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve under åben himmel, er afgørende. En veludhvilet og veloplagt eventyrer har langt større chance for at overleve denne livsstil."},
  [96608] = {c="Nu da vi har styr på det grundlæggende, hvorfor tager du så ikke hen og lærer erhvervet af trænerne i den nærliggende landsby. De lærer dig også, hvordan man laver et lejrudstyr, der passer til dit nye erhverv.", p="At have de færdigheder, der skal til for at overleve under åben himmel, er afgørende. En veludhvilet og veloplagt eventyrer har langt større chance for at overleve denne livsstil."},
  [96626] = {c="Det gør dig i stand til at slå lejr hvor som helst i vildmarken. Det, du har lært, er kun det grundlæggende, så du vil ikke kunne placere alt for meget udstyr omkring den.\n\nForbedr dine madlavningsfærdigheder, og du lærer måske at lave endnu større bål.\n\nDu kan også lære det grundlæggende i lejrudstyr hos andre håndværkstrænere, hvis du er dygtig i deres færdigheder.", p="Et godt bål er grundlaget for enhver veludstyret lejr."},
  [96627] = {c="Tak for din beskyttelse, YOUR_CLASS7. Den marskal er en rendyrket kujon.\n\nHej, du ser også ud som en eventyrer. Vil du høre om lejren?"},
  [96628] = {c="Siger du, at den er fra højlænderne? Ja, den kan jeg få brug for. Tak, YOUR_CLASS7.\n\nHej, du ser også ud som en eventyrer. Vil du gerne høre om lejrliv?", p="Er du her for at høre om campering i det vilde?"},
  [96629] = {c="Det gør dig i stand til at slå lejr hvor som helst i vildmarken. Det, du har lært, er kun det grundlæggende, så du vil ikke kunne placere alt for meget udstyr omkring den.\n\nForbedr dine madlavningsfærdigheder, og du lærer måske at lave endnu større bål.\n\nDu kan også lære det grundlæggende i lejrudstyr hos andre håndværkstrænere, hvis du er dygtig i deres færdigheder.", p="Et godt bål er grundlaget for enhver veludstyret lejr."},
  [96638] = {c="Vi har det godt!"},
  [96646] = {c="Det gør dig i stand til at slå lejr hvor som helst i vildmarken. Det, du har lært, er kun det grundlæggende, så du vil ikke kunne opstille for mange genstande omkring den.\n\nForbedr dine madlavningsfærdigheder, og du lærer måske at lave endnu større bål.\n\nDu kan også lære det grundlæggende i at indrette dine lejre hos andre håndværkstrænere, hvis du er dygtig i deres færdigheder.", p="Et godt bål er fundamentet for enhver god lejr."},
  [96652] = {c="Er det min dagbog? Jeg har været uden den i et stykke tid. Tak, YOUR_CLASS7.\n\nHej, du ligner en eventyrer. Vil du lære om camping?", p="Er du her for at lære om lejrliv i det vilde?"},
  [96655] = {c="Det gør dig i stand til at slå lejr hvor som helst i vildmarken. Det, du har lært, er kun det grundlæggende, så du vil ikke kunne opstille for mange genstande omkring den.\n\nForbedr dine madlavningsfærdigheder, og du lærer måske at lave endnu større bål.\n\nDu kan også lære det grundlæggende i at indrette dine lejre hos andre håndværkstrænere, hvis du er dygtig i deres færdigheder.", p="Et godt bål er fundamentet for enhver god lejr."},
  [96656] = {c="Jeg er ikke forbundet med Den Blodrøde Korstog, hvis du ikke kunne se det. Jeg er bare en eventyrer, der holder en pause, før min næste tur ud i vildmarken.\n\nHej, du ser ud som en eventyrer. Vil du gerne lære om lejrliv?"},
  [96658] = {c="Det gør dig i stand til at slå lejr hvor som helst i vildmarken. Det, du har lært, er kun det grundlæggende, så du vil ikke kunne opstille for mange genstande omkring den.\n\nForbedr dine madlavningsfærdigheder, og du lærer måske at lave endnu større bål.\n\nDu kan også lære det grundlæggende i at indrette dine lejre hos andre håndværkstrænere, hvis du er dygtig i deres færdigheder.", p="Et godt bål er fundamentet for enhver god lejr."},
  [96659] = {c="Høvding Falkevind sendte dig? Jeg sagde til ham dengang, at jeg ikke havde brug for en belønning, men det ser ud til, at han ikke lyttede. Tak, YOUR_CLASS7.\n\nHej, du ligner en eventyrer. Vil du gerne lære om lejrliv?", p="Er du her for at lære om lejrliv i det vilde?"},
  [96779] = {c="Efter Tomas' død vil Durnholde-fæstningen helt sikkert falde i kaos. Almindelige håndlangere fra Syndikatet mister ofte overblikket uden en leder.\n\nGodt gået, YOUR_NAME. Måske beder jeg dig snart om flere opgaver."},
  [96783] = {c="<Du tager uniformen og gør dig klar til næste fase af din mission.>"},
  [96821] = {c="Peonerne har været bange for at rejse sydpå i noget tid, Joruus. Nu hvor du har ryddet lidt op på vejen, kan vi sende dem tilbage til arbejdet."},
  [96822] = {c="Disse krigere vil altid blive husket, Ulvarg. Det har du sørget for.", p="Har du gjort det, jeg bad dig om?"},
  [96825] = {c="Jeg skal lave noget lækkert ud af dem og gemme frøene til at så. En dag får vi kaktusser, der vokser overalt omkring Orgrimmar!", p="Har du fundet frugterne?"},
  [96873] = {c="Godt klaret. Ærgerligt med de dræbte trolde, men når besværgelserne er fjernet, kan deres ånder hvile i fred.", p="Hvad har du til mig, Thay?"},
  [96874] = {c="Disse torne er hårdere, end jeg regnede med, Gnavfik! Håndværket med dem er måske ikke så nemt, som jeg troede... men jeg skal nok arbejde på det!", p="Hva'?"},
  [96875] = {c="Dit arbejde hjælper Ogrehjem med at vokse. Husk på det, når du går rundt i byens gader.", p="Hva'?"},
  [96895] = {c="Bliv nede og prøv at være usynlig, YOUR_CLASS7. Med disse kultister er der ikke noget at spøge med."},
  [96896] = {c="Jeg har planer om at blive her et stykke tid og snakke med flere af mine venner, men jeg vender snart tilbage til Lysets Håbs Kapel i Østpestlandene. Hvis du nogensinde havner der, så sig hej. Vi har altid brug for mere hjælp fra dygtige eventyrere."},
  [96897] = {c="Tak for din hjælp, YOUR_CLASS7. Hvis vi ikke vil have, at Herrelandets historie gentager sig, må vi være årvågne, når sådanne trusler truer os."},
  [96898] = {c="Tak. Det burde bremse Pestens indsats på dette område. Jeg formoder, at Tirisfals indbyggere vil grave disse krystaller op af jorden i årevis, men at fjerne de mest synlige af dem kan kun hjælpe.", p="Jeg vil fraråde dig at komme i for tæt fysisk kontakt med de krystaller. Selv knust og udtømt er magien i de nekrotiske krystaller yderst farlig."},
  [96899] = {c="Dette sted er fyldt med minder for mig. Dette sted blev engang holdt af Sølvdaggry. Det var herfra, vi forberedte os til mange slag og skærmydsler med Pesten under deres sidste fremstød mod Tirisfals Lysninger.\n\nDa vi trak os tilbage til Pestlandene, frygtede jeg, at den ville falde i ruiner. Mine frygt blev bekræftet, men jeg er glad for, at Danitha og hendes korsriddere nu har overtaget ansvaret for den.\n\nHun kaldte endda fæstningen efter... en fælles ven."},
  [97003] = {c="Imponerende, YOUR_CLASS7. Ingen vil tvivle på mine historier, når jeg vender tilbage til Ørgrimmar med dette dystre bevis på, at disse monstre findes. Vær sikker på, at æren er din, men jeg vil fortælle højlydt om dine bedrifter.\n\nLokk-tar!", p="Det krævede kræfter fra seks erfarne krigere at fælde et af disse væsener, og alligevel lykkedes det det at dræbe fire af os, før vi kunne fælde det.\n\nHvis disse monstrøse bæster skulle dukke op i større antal, kunne den skade, som Tornesvin kunne gøre på landet, blive katastrofal."},
  [97005] = {c="Mine faldne mænd vil sove roligere, vidende at der er ét monster mindre i verden. Du har gjort det godt, og du er en ægte og urokkelig forsvarer af Alliancen. Tak.\n\nGå med ære, Grym.", p="Det krævede seks af os at fælde et af disse væsener, og alligevel lykkedes det det at dræbe alle undtagen mig og en anden, før vi kunne fælde det.\n\nSå langt fra Alliancens lande burde jeg lade det være. Lyset ved, at jeg ikke vil miste meget søvn over nogle vilde taurener eller orkiske brutaler. Men mine faldne brødres ære kræver handling."},
  [97222] = {c="Jep. Der er en grund til, at hængslet åbner indad mod dem, så folk ikke blokerer døren ved at efterlade ting, hvor de har lyst.\n\nLad os nu betragte os selv som professionelt bekendte, YOUR_CLASS7.\n\nVi respekterer dit arbejde og forventer, at du respekterer vores."},
  [97223] = {c="Tak, Askegrim. Jeg er glad for, at vi kan bevare hendes blodlinje og opdrage dem til vores allierede. Du har gjort vores stamme en stor tjeneste.", p="Blodtænderne er kendt for list og hurtighed, og de er fremragende følgesvende, når man opdrager dem fra æg til voksen alder.\n\nDesværre er voksne raptorer meget svære at træne, og jeg har gentagne gange forsøgt at fange Matriarken. Men hun er blevet for farlig på det seneste.\n\nJeg håber stadig at bevare hendes arv ved at opdrage hendes unger som følgesvende her i Sen'jin."},
  [97225] = {c="I dag har du udført en stor gerning for vores stamme.\n\nI modsætning til nogle stammer er vores slægtskab med vores loa fyldt med respekt og ærefrygt, og vi står dybt i gæld til dem.\n\nJeg ville ikke ønske, at Mørk Spydet mister loaernes gunst.", p="Har du fundet vores loa-idoler, Enve? Vi må snart genoptage vores ritualer."},
  [97242] = {c="Denne type vandkøller og græsspyd er unik for Orgrimsborg. Når man drikker fra Azsaras bjergkilde og lever af sved og blod gennemvædet af mineralstøvet fra vores stenede jorder, rummer disse urter kraftfulde kræfter skjult i sig.\n\nJeg giver dem til Hjelmak, som måske kan få Huuts øre tilbage med en praktisk lektion.", p="Vi opdager formuleringer og opskrifter og viser gamle ingredienser frem til nye generationer, som eksperimenterer med dem på deres egen måde."},
  [97243] = {c="Du kom med en fakkel. Ja, unge YOUR_CLASS7, jeg kan lære dig at lytte til ildens kald. Det bliver ikke let, men intet, vi gør i dette land, er nogensinde let.", p="Nå, Natteravn? Hvad har du dér?"},
  [97244] = {c="Vindspejderne glemmer ikke, og blod betales altid med blod. Jeg er glad for, at du var i stand til at levere den endelige, smertefulde påmindelse om vores kodeks til forræderen.\n\nDette hjerte bliver dog ikke det, der fodrer flammerne i dag. Der er én anden opgave, der skal udføres.", p="Forræderens hjerte er et kraftfuldt reagens. Flammerne vil gerne modtage sådan et offer og brænde kraftigere, når det fortæres."},
  [97245] = {c="Nu har vi det, vi behøver. Vi har tændt Den Evige Flamme, og vi vil forbinde os med ildånderne.", p="Kuramåde-ånden er evig, og den vil vise sig igen, når den er nødvendig. Hans maske er en kilde til stor magt, og den vil vise sig uvurderlig for det ritual, vi må fuldføre."},
  [97246] = {c="Selvfølgelig. Migis forældre og jeg har en aftale om, at Migi får en pakket frokost hver dag, men jeg kan kun sikre, at drengen får mad, hvis han rent faktisk kommer for at hente den.\n\nNogle gange henter han ikke sin mad flere gange om ugen, og jeg spekulerer på, hvor han får energien fra til at blive og lege."},
  [97249] = {c="Brændstans kød? Er det til en af os?\n\nOh!\n\nWow... det dufter virkelig godt! Mmmm.\n\nTak, fordi du kom med mig til middag. Jeg kan lugte mig til, hvad Brændstan vil servere hver dag, når mine venner og jeg går forbi Grommasz' Ildsted. Det smager ligesom mine yndlingsting med den søde glasur! Men det er anderledes. Jeg kan lide kraftige smagskrummer.\n\nHvis det bliver så lækkert hver dag, tror jeg, vi må holde pause i spillet for at spise middag sammen!", p="Jeg tror, vi kan vinde den her..."},
  [97250] = {c="Rygterne var sande! Jeg havde forventet det; spændingerne har kogt længe langs østkysten. Jeg vidste, at det kun var et spørgsmål om tid, før konflikten kravlede ind på vores jord.\n\nJeg er dog skeptisk over, om vi stod bag ødelæggelsen af kroen. For mange civile fra Horden er afhængige af den rute til handel og rejser. Måske kunne du undersøge sagen nærmere, hvis du har tid.\n\nUanset hvad, så er dagens handling en sejr for Horden og en alvorlig advarsel til Alliancen!"},
  [97253] = {c="Whoooa! Flot gjort! Du reddede mig fra endnu en udholdelig forelæsning fra Klikkefjeder om metalets pris. Endnu vigtigere er det, at jeg nu kan springe i gang med at bygge min næste prototype.\n\nUhhh, jeg havde ingen genitiv-genital-belønning planlagt... Kan du lide æsker?", p="Ikke et ord fra dig, før dine lommer klinger af metal!"},
  [97257] = {c="Det er gjort. Den Evige Flamme brænder igen.\n\nDin prøvelse er nu fuldført. Jeg er glad for at kunne give dig Ildtotemet. Brug denne kraftikon godt på dine rejser, Bilbøn.\n\nHusk dog, at elementarplanets kraft tjener dem, der respekterer den, og fortærer dem, der ikke gør. Sådan er vores vej.", p="Godt at du kom så langt. Du ærer Vindspejderne, Bilbøn."},
  [97263] = {c="Hvad! Jeg gik hver dag hen til postkassen ved banken og ventede på den pakke! Den by må få styr på sin indretning. Ikke lettere at navigere i end Ørnerede-toppen!\n\nLad os se, hvad jeg har... værktøj til at skære totems... en reserveøkse... en goblin-apparat? Det har jeg ikke bestilt! Ah, jeg sender det bare tilbage.\n\nEr, øh... jeg mener... tak fordi du kom forbi. Her er noget for besværet.", p="Hvad har du dér?"},
  [97277] = {c="Aye, det overrasker mig ikke at høre, at den snelepard lavede et måltid af vildsvinet, vi havde gjort klar til stegning!\n\nGoz får én ting mindre at bekymre sig om nu, hvor du er kommet med hans dagbog. Nu kan han måske samle al sin energi om at komme på benene.\n\nTak, Søger. Tag noget som et Mærke for min taknemmelighed, for at du tog turen og beskyttede bakkerne.", p="Stakkels Goz bekymrer sig mere om sin mekaniske gåmaskine end om sig selv. Han siger, at hvis nogen falder over denne bog, så er han klar til at gå under. Hah! Derfor sagde jeg til ham, at han bare skulle lade sit arbejde blive hjemme!"},
  [97279] = {c="Tak for at returnere disse våben, Gnistret. Jeg går i gang med at reparere dem til den næste bølge af rekrutter.", p="Trommeka, YOUR_CLASS7. Grumsak sagde, at jeg skulle forvente dig. Godt at se dig i ét stykke!\n\nHar du været i stand til at samle de træningsvåben, jeg bad om?"},
  [97281] = {c="Woah, hvor har du fundet sådan nogle fede ting? Du ved, det minder mig om noget andet, som min chef Gazlowe altid fortalte mig..."},
  [97282] = {c="Hej, tak, makker! Du har været en stor hjælp for mig, og tak for det.\n\nLad os håbe, at jeg kan oplade det hele ved hjælp af disse organer. Jeg vædder på, at det får de fordømte harpyer til at tænke sig om to gange, før de angriber min karavane. Jeg håber da helt sikkert, at det virker.\n\nUnder alle omstændigheder har du holdt din side af aftalen. Tag dette for din ulejlighed.", p="Vi kan blive overraskede over, at de med et navn som tordenøgle skyder lyn i stedet for at brøle som torden.\n\nJa, de skyder. Skyder lyn, mener jeg.\n\nTro mig, det er en lektie, man kun får én gang, hvis man er heldig."},
  [97288] = {c="Oho! Jeg tror, jeg kender det hoved. Et grusomt puds fra vores Mørke Dame. Lækkert.\n\nJeg tror, jeg kan bruge det til noget.", p="Hvad har vi her?"},
  [97289] = {c="<Kroppen rykker til live, panisk, mens den gen-oplever sine sidste øjeblikke.>\n\nDu...", p="<Monstret forbliver livløst uden hoved til at styre det.>"},
  [97290] = {c="Han samarbejder ikke, hva'? Fortræffeligt. Jeg elsker altid en udfordring."},
  [97291] = {c="De bliver lækre. Lad os se, hvor meget bravader vores ærede gæst beholder, når han er underkastet mit mesterværk.", p="Det vil være dejligt at få vores tabte får tilbage til flokken, synes du ikke?"},
  [97292] = {c="Fint. Lad hans krop koge en stund. Giv ham tid til at vænne sig til sit nye hjem.\n\nJeg har ikke meget brug for ham endnu, men vi holder øje med ham. Jeg har mange planer for Otmars fremtid.", p="For Othmars forbrydelser mod Mørkedamen er det mindste, han fortjener, at blive anbragt under dette drivende eksemplar.\n\nOg det er morsomt..."},
  [97326] = {c="Hvordan kan du overhovedet bære alle de klipper!\n\nDe er fantastiske. De fleste har endda en pæn flad side. Nu hvor du har slæbt dem herhen, kan vi flytte dem rundt i mudderet, præcis dér, hvor vi vil have dem.\n\nTak, Gnavfik!", p="Det er rart, at man ikke altid behøver at sidde i mudder!"},
  [97485] = {c="Du har gjort det godt.\n\nTak, fordi du tog dig tid til at udføre en af vores højt værdsatte traditioner, YOUR_RACE7. Jeg håber, at du på din rejse får mange lejligheder til at takke.\n\nHvis du nogensinde vil udføre ritualet igen, bør du kunne købe de komponenter, jeg bad dig samle, igen.\n\nGå med varme, Ånd'she.", p="Der er mange lejligheder, hvor man kan vælge at strø røgelse ud i vinden. Du kan bede Moder Jord om at beskytte nogen, velsigne en jagt, markere en begivenhed eller endda søge råd hos vores forfædre.\n\nEller det kunne være noget helt andet.\n\nSelvom handlingen udføres med fromhed, er det ikke en strengt ceremoniel sag. Der er normalt nogle traditionelle skridt, man følger, når man udfører handlingen, men mange stammer har forskellige skikke."},
  [97558] = {c="Ah, perfekt! Tak, fordi du skaffede disse. Jeg lover, at de bliver godt brugt.", p="Har du samlet det skind, jeg bad dig om? Vores lager er ved at slippe op.\n\nDet kan virke mærkeligt at bede om murlok-skind, men det egner sig godt til indre hinder eller overflader som kinder og læber.\n\nHinderne fra tusmørkeflagermusenes vinger er særligt gode til de finere områder, som ansigter og fingre. Det forhindrer, at huden bliver for... tyk."},
  [97891] = {c="Ah, vidunderligt! Jeg har ventet på Alexanders eliksir. De sidste seks, han sendte, blev ustabile undervejs, men du nåede frem lige i tide!\n\nSå, tag det her som belønning for din indsats. Det er alt for nu, medmindre du har andre ærinder til mig?\n\nHvis ikke, så forsvind, så jeg kan fortsætte mine eksperimenter uden forhindringer."},
  [97894] = {c="Har Gamle Borgi sendt dig? Han holder altid øje med mig.\n\nVi kunne nok bruge et par ekstra hænder her. Forretningen er næsten gået i stå på grund af den seneste tragedie, og jeg tror, du kunne hjælpe med at rette tingene op."},
  [97899] = {c="Der har du vejledningen til din egen Manabrønd. De fleste gider ikke lejre opslået midt i byen, så du bliver nødt til at tage ud i vildmarken, hvis du vil prøve det.\n\nIngen lejr er komplet uden et bål. Du får brug for et af dem som grundlag for at campere. De fleste kokke kan lære dig at lave ild. Find en, der kan træne dig i madlavning, hvis du endnu ikke har lært det grundlæggende."},
  [97901] = {c="Der har du det, nu kan du fremstille din egen Fortryllet Lut. De fleste gider ikke lejre opslået midt i byen, så du må ud i vildmarken, hvis du vil prøve det.\n\nIngen lejr er komplet uden et bål. Du får brug for et af dem som grundlag for lejrlivet. De fleste kokke kan lære dig at lave ild. Find en, der kan træne dig i madlavning, hvis du endnu ikke har lært det grundlæggende."},
  [97903] = {c="Værsgo, nu kan du lave dit eget Førstehjælpssæt. De fleste gider ikke campere midt i byens centrum, så du bliver nødt til at gå ud i det vilde, hvis du vil teste det.\n\nÅh, og husk, at ingen lejr er komplet uden et bål. Du skal have et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har færdighederne endnu, så find en, der kan træne dig i madlavningens kunst, så du lærer det basale.", p="Jeg kan lære dig det, når du får færdigheder i dit erhverv."},
  [97904] = {c="Se, nu kan du lave dit eget Akvarium. De fleste gider ikke slå lejr midt inde i byen, så du bliver nødt til at tage ud i den vilde natur, hvis du vil prøve det.\n\nIngen lejr er komplet uden et bål, makker. Du skal have et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Spørg en, der kan træne dig i kogekunst, hvis du ikke har lært det grundlæggende endnu.", p="Jeg kan lære dig det, når du får færdigheder som fisker."},
  [97905] = {c="Se, nu kan du lave dit eget Røgelseslys. De fleste gider ikke slå lejr midt inde i byen, så du bliver nødt til at tage ud i den vilde natur, hvis du vil prøve det.\n\nIngen lejr er komplet uden et bål, makker. Du skal have et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Spørg en, der kan træne dig i kogekunst, hvis du ikke har lært det grundlæggende endnu."},
  [97914] = {c="<Baros åbner brevet og begynder at læse det, hans smil forsvinder.>", p="Jeg dufter havet af dig, ven!\n\n<Baros ler.>\n\nHvad bragte dig til Stormvind?"},
  [97916] = {c="Værsgo, nu kan du lave din egen Slibesten. De fleste gider ikke campere midt i byens centrum, så du bliver nødt til at gå ud i det vilde, hvis du vil teste den.\n\nÅh, og husk, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har færdighederne endnu, så find en, der kan træne dig i madlavningens kunst, så du lærer det basale."},
  [97918] = {c="Værsgo, nu kan du lave din egen Ingrediensrobot. De fleste gider ikke campere midt i byens centrum, så du bliver nødt til at gå ud i det vilde, hvis du vil prøve.\n\nÅh, og husk, at ingen lejr er komplet uden et bål. Du skal have et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har færdighederne endnu, så find en, der kan træne dig i madlavningens kunst, så du lærer det basale."},
  [97919] = {c="Værsgo, nu kan du lave dit eget Førstehjælpssæt. De fleste gider ikke campere midt i byens centrum, så du bliver nødt til at gå ud i det vilde, hvis du vil prøve.\n\nÅh, og husk, at ingen lejr er komplet uden et bål. Du skal have et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har færdighederne endnu, så find en, der kan træne dig i madlavningens kunst, så du lærer det basale."},
  [97920] = {c="Der har du det, nu kan du fremstille dit eget Akvarium. De fleste gider ikke lejre opslået midt i byen, så du må ud i vildmarken, hvis du vil prøve det.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du får brug for et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har evnerne endnu, så find en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende.", p="Jeg kan lære dig det, når du får færdigheder som fisker."},
  [97921] = {c="Værsgo, nu kan du lave dit eget Røgelseslys. De fleste gider ikke campere midt i byens centrum, så du bliver nødt til at gå ud i det vilde, hvis du vil prøve.\n\nÅh, og husk, at ingen lejr er komplet uden et bål. Du skal have et af dem, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har færdighederne endnu, så find en, der kan træne dig i madlavningens kunst, så du lærer det basale."},
  [97923] = {c="Se der, nu kan du lave din egen Magisten. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve den.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97924] = {c="Se der, nu kan du lave din egen Lejrstol. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve den.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97925] = {c="Se der, nu kan du lave din egen Mobiliseringsbanner. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve den.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97926] = {c="Triste nyheder, sandelig. Ikke desto mindre takker jeg dig for at påtage dig rejsen.\n\nNår hverken Stormvind eller Darnassos kommer os til undsætning, synes Auberdins skæbne at være vores egen at bestemme.", p="Du er tilbage. Hvilke nyheder kommer der fra Stormvind?"},
  [97931] = {c="Se der, nu kan du lave dit eget Førstehjælpssæt. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve det.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97932] = {c="Se der, nu kan du lave dit eget Akvarium. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve det.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97933] = {c="Se der, nu kan du lave dit eget Røgelseslys. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve det.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97942] = {c="Se der, nu kan du lave dit eget Førstehjælpssæt. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve det.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97943] = {c="Se der, nu kan du lave dit eget Akvarium. De fleste bryder sig ikke om at slå lejr midt i byen, så du bliver nødt til at tage ud i det vilde, hvis du vil afprøve det.\n\nÅh, og husk bare, at ingen lejr er komplet uden et bål. Du skal have et, før du slår lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, bør du måske spørge en, der kan træne dig i kogekunst, så du lærer det grundlæggende."},
  [97951] = {c="Ja, så kan du nu lave din egen Manabrønd. De fleste bryder sig ikke om lejre midt i byen, så du må ud i det vilde, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du skal have et, før du begynder at indrette din lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, så spørg en, der kan oplære dig i kogekunst, så du lærer det grundlæggende."},
  [97953] = {c="Præcis, nu kan du lave din egen Fortryllet Lut. De fleste folk gider ikke lejre bygget midt i byen, så du bliver nødt til at tage ud i vildmarken, hvis du vil teste det.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du skal bruge et, før du går i gang med dit lejrliv. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, kan du overveje at opsøge en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [97955] = {c="Ja, så kan du nu lave din egen Førstehjælpskasse. De fleste bryder sig ikke om lejre midt i byen, så du må ud i det vilde, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du skal have et, før du begynder at indrette din lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, så spørg en, der kan oplære dig i kogekunst, så du lærer det grundlæggende.", p="Jeg kan lære dig det, når du har fået nogle færdigheder i dit erhverv."},
