  [97972] = {c="Ja, så kan du nu lave din egen Indsamlingsbanner. De fleste bryder sig ikke om lejre midt i byen, så du må ud i det vilde, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du skal have et, før du begynder at indrette din lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, så spørg en, der kan oplære dig i kogekunst, så du lærer det grundlæggende."},
  [97973] = {c="Ja, så kan du nu lave din egen Indsamlingsbanner. De fleste bryder sig ikke om lejre midt i byen, så du må ud i det vilde, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du skal have et, før du begynder at indrette din lejr. De fleste kokke kan lære dig at lave ild. Hvis du ikke har gjort det endnu, så spørg en, der kan oplære dig i kogekunst, så du lærer det grundlæggende."},
  [97977] = {c="Åh, det er endnu værre, end jeg troede.\n\nDisse graveringer fortæller os, at Knudefyrene er begyndt at få mareridt om at blive udslettet af en eller anden stor skygge. Snart forvandlede frygten sig til vrede -- og skyggen til deres gamle alviske venner. Tanken om at din egen hjerne glider dig af hænde...\n\nVores eneste håb er, at det måske kan hjælpe os med at forstå, hvad der foregår på Teldrasil. Tak for din hjælp, Djangø.", p="Bekymr dig ikke om de større totemer, du måtte finde. Jeg ville ikke vide, hvad jeg skulle gøre med dem, hvis du fandt en måde at få dem hertil på!"},
  [97979] = {c="Du har set det, vores gudinde giver. Brug det klogt, så forlader hun dig aldrig."},
  [97985] = {c="Fremragende! Jeg kan næsten ikke holde mig for begejstring. Og hjertet har stadig elektriske impulser? Imponerende. Så behøver jeg ikke genoplive det med stød!\n\nDette hjerte vil blive en fortrinlig tilføjelse til abominationen, og det har helt sikkert den rette størrelse, hvis disse noter er korrekte.\n\nAh, jeg elsker, når en plan går op.", p="Åh, du er kommet tilbage i ét stykke! Det er en skam, for din krop og dine organer ville have været perfekte til mine eksperimenter."},
  [98013] = {c="Bekymr dig ikke, min unge ven. At plyndre sit eget hjem for en eller anden sort herre...\n\nDet er unådeligt."},
  [98021] = {c="Jeg har tigget Stormvind om hjælp i månedsvis, og så sender de mig en tynd alf? Nå, den fattige må tage, hvad han kan få.\n\nVelkommen til Vestfald, YOUR_CLASS7. Lad os se, om vi ikke kan hive dig ind i noget."},
  [98024] = {c="Hvad? Alv? Og du siger, at Krigshøvdingen sendte dig?\n\n<Tork knurrer skarpt, mens han stirrer grundigt på dig.>\n\nDu ser lidt for mager ud efter min smag, men det er lige meget. Her blomstrer du og overlever, eller også dør du. Sådan er tingene i disse lande."},
  [98025] = {c="Godt at vide, at problemet er løst, men det gør mig ondt, at vi ikke kunne finde en anden udvej. Jai'vhanøl har i lang tid været en slags vogter af dette område, og jeg er ikke sikker på, hvad der kunne have fået hende til at falde ned i galskaben.\n\nUanset dette, tak for din tjeneste i dag, YOUR_CLASS7. Vejene til Auberdin er igen sikre at rejse på.", p="Hilsen YOUR_CLASS7 - hvad kan vi hjælpe dig med i dag? Kommer du måske for at få din belønning for Jai'vhanøl?"},
  [98027] = {c="Hovsa! Jeg kan ikke tro, du fandt den. Jeg var sikker på, at jeg havde gennemrodet det hele!\n\nJeg tabte den, da jeg bragte forsyninger ud til en af vores forposter, men efter at have kigget hele vejen igennem gav jeg op.\n\nTak, fordi du bragte den. Det er en gave fra mine døde forældre, og jeg kan ikke sige, hvor meget det betyder at få den igen."},
  [98046] = {c="Tag ikke notits af Ærkedruiden. Han har meget på sine skuldre, nu hvor Malfurion er væk.\n\nVent! Der er stadig et par dråber tilbage i hætteglasset! Måske var det derfor, hans besværgelse slog fejl?", p="Hvad kan jeg gøre for dig?"},
  [98059] = {c="Godt klaret, soldat. Jeg ved, at du ikke står i vores rækker, men vi afviser aldrig hjælpende hænder.\n\nHvis de ikke svarer på DETTE brev, må vi tale til dem på en mere gennemtrængende måde.\n\nVi holder dig i reserve til kontakt med civile, skulle behovet opstå igen."},
  [98065] = {c="Hjorthelm har gjort meget i min elskedes fravær, men han er ikke Malfurion. Og han leder ikke Darnassos' anliggender - den byrde hviler udelukkende på mig.\n\n<Tyrandes ansigt blødgør sig.>\n\nJeg beklager. Som du nok har set, har vi mange udfordringer at overvinde.\n\nFandrel er nu Ærkedruide, og jeg beder dig respektere hans embede. Men hans gerninger drejer sig om druidisme, mens mine ikke blot drejer sig om Elunes, men om virkelig at lede vores folk, sådan som hun ønsker det.\n\nHver dråbe af dette vand er velsignet af vores gudinde. Tak, fordi du reddede hende.", p="Fortæl mig venligst, hvad du ønsker. Jeg har en by at styre og et folk at lede."},
  [98067] = {c="Tak for din hjælp. Selvom jeg finder ro i de daglige ritualer, er det dejligt at få et øjeblik til eftertanke i stedet."},
  [98069] = {c="Tak, YOUR_NAME. Disse forsyninger vil hjælpe os med at overleve, indtil næste leverance.", p="Fik du genvundet provianten, som harpyerne stjal?"},
  [98070] = {c="Det er gode nyheder! Jeg vil fortælle vores leverandører, at harpyerne er blevet besejret. I det mindste én trussel mindre for fremtidige konvojer."},
  [98071] = {c="Det var lige den humlelugt, jeg har savnet! Du har gjort mig en stor tjeneste, YOUR_NAME. Hver gang jeg selv tager til Garok-bakken, går der dage med det. Det er svært for mig at komme ud af de mure, når jeg først har slået mig ned.\n\nDet er dejligt at gemme lidt gamle smage på hylden til andre dværge.\n\nTag noget småt som tak for hjælpen.", p="Vil du prøve et nyt øl?"},
  [98093] = {c="Tak for hjælpen, Sygbønne. Jeg vil give Taurajo-lejren besked om, at du reddede mig. Jeg er heldig, at du hjalp mig, jeg kunne have siddet fast deroppe hele dagen!\n\nDet er alt, hvad jeg kan give dig, men jeg håber, at det kommer til nytte.\n\nJeg går, så snart jeg er kommet sikkert ned fra træet."},
  [98197] = {c="Åh! Lidt fugtig, men ikke noget, et par dage i solen ikke kan rette op på.\n\nTak, YOUR_CLASS7. Det er rart ikke kun at være afhængig af forsendelser fra Theramøre eller Auberdin en gang imellem!", p="Hold dig skarpt under bølgerne. Der er mange skumle ting derude!"},
  [98209] = {c="Nord'el overlevede? Umuligt... efter så mange år!\n\nVores gudinde er virkelig vidunderlig!\n\nTak fordi du bragte ham herhen. Et sjældent lys i de mørke tider, vi for nylig har været ude for, og et symbol ikke blot på Elunies nåde, men også på vores folks vedvarende vilje til at overleve uden vores udødelighed.\n\nJeg sørger for, at han bliver transporteret sikkert til Darnassos, hvor han kan blive ordentligt plejet.", p="Velkommen til Auberdin, YOUR_CLASS7. Hvordan kan vi hjælpe på din rejse?"},
  [98216] = {c="Se derhenne - ser du, hvordan Goaz-stenen begynder at lyse, når den kommer tæt på nøglen? Jeg kan næsten læse nogle af de næste ord...\n\nVi har stadig meget at lære om denne Goaz. Jeg har den fornemmelse, at det kun er isbjergets spids af noget enormt!", p="Gjorde stenen noget?!"},
  [98221] = {c="Jernsmede også? Nekrosh har bestemt arvet sin fars ambitioner!\n\nMen han mangler en hær af slavebundne røde drager, som gjorde så store skader under krigen. Han har taget et risikabelt skridt, det er sikkert — og han vil betale en høj pris for det.", p="Krige vindes — og tabes — med informationer. Husk det godt."},
  [98230] = {c="Hvis du er kommet for at hjælpe, siger jeg ikke nej. Hjælp er forfærdelig svær at få fat i for tiden."},
  [98247] = {c="Du er kommet til rette sted! Jeg er glad for at kunne registrere dig som en af vores partnere. Ingen kontrakter at underskrive og ingen forpligtelser, der tynger dig. Alt, vi beder om, er din pligtfølelse til at hjælpe med at fuldføre eller returnere en af vores leverancer, som du støder på på dine rejser.\n\nNår du gør det, bliver du belønnet med Købmandens Velvilje, som lader dig købe de varer og tjenester, vi tilbyder her. Faktisk er der lidt her til at komme i gang.\n\nHar du tilfældigvis en kasse, det her kom fra?", p="Ak, hilsner! Hvad kan jeg gøre for dig?"},
  [98248] = {c="Du har fundet det rette sted og taler med den rette person! Jeg kan registrere dig som en af vores nye medarbejdere. Da du ingen papirer har, kan jeg ikke være besværlig med mere af det.\n\nAlt, hvad vi beder om, er, at du hjælper med at tage dig af de beskadigede forsyninger, du støder på på dine rejser. Det vil give dig Købmandens Velvilje, som du kan bruge til at købe varer og tjenester her. Her er lidt, så du kan få dig selv en håndsrækning!\n\nHar du tilfældigvis den kiste, det kom fra?", p="God dag, rejsende. Hvad kan jeg gøre for dig?"},
  [98283] = {c="Slagtningens død vil genoprette balancen i hans flok. Måske giver det nok tid til hele det økosystem, de understøtter.\n\nVi får se, men jeg takker dig for indsatsen alligevel.", p="Rådneklo er kommet ned fra deres hjem i Modansøen, nu drevet til vanvid.\n\nSikke et spild af livets gaver."},
  [98284] = {c="Der har du det, nu kan du lave din egen Fortryllet Lut. De fleste bryder sig ikke om lejre slået op midt i byen, så du bliver nødt til at gå ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du får brug for et, før du slår din base op. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du tage kontakt til en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [98285] = {c="Der har du det, nu kan du lave din egen Ingrediensrobot. De fleste bryder sig ikke om lejre slået op midt i byen, så du bliver nødt til at gå ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du får brug for et, før du slår din base op. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du tage kontakt til en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [98286] = {c="Der har du det, nu kan du lave din egen Fortryllet Lut. De fleste bryder sig ikke om lejre slået op midt i byen, så du bliver nødt til at gå ud i vildmarken, hvis du vil teste den.\n\nÅh, og husk, ingen lejr er komplet uden et bål. Du får brug for et, før du slår din base op. De fleste kokke kan lære dig at lave ild. Hvis du endnu ikke har gjort det, kan du tage kontakt til en, der kan træne dig i madlavningens kunst, så du lærer det grundlæggende."},
  [98291] = {c="Jeg har ikke tænkt mig at sørge over deres slægt. De fik, hvad de fortjente."},
  [98297] = {c="Jeg kan ikke takke dig nok, YOUR_NAME. Virkelig, jeg kan ikke gøre nok for det, du gjorde i dag.\n\nDer er meget tilbage at gøre, før Grimbatol igen hører latteren fra små dværgebørn, men det er et godt skridt nærmere.\n\nFor alle de dværge, der gik tabt i de mørke dage, kan vi stadig genvinde det, der var vores.\n\nJeg håber det i det mindste."},
  [98298] = {c="Det ser ud til, at jeg alligevel får det sidste ord, haha! Arugel var virkelig en tosse. Og jeg, Dalar Morgenvæver, afslørede ham som svindler.\n\nDisse stykker er hele det bevis, jeg behøver for at vise, at forbandelsen intet har med den latterlige fejl at gøre.\n\nDesværre betyder det, at hans middel også er værdiløst. Det ser ud til, at jagten på en løsning på worgen-forbandelsen stadig er i gang.", p="Hugtænder, kløer, indvolde. Det betyder ingenting for mig. Det nemmeste er at undersøge noget ved selv at se indmaden."},
  [98299] = {c="Det ser ud til, at Gilneanerne ikke er særlig interesserede i at lade nogen komme over deres mur. Heldigvis. Det betyder, at der næsten ingen chance er for, at worgen-forbandelsen spreder sig til deres by.\n\nKan du forestille dig fordærvelsen, hvis hele riget var smittet?"},
  [98310] = {c="Ved Magnis skæg, de er smukke! Vent, ser I det?! Hold hjerterne tættere på Gåsestenen et øjeblik...\n\n<Der dukker ny tekst op på stenen, lysende med et svagt flimrende skær.>\n\nHm, svær at læse. „Kødets forbandelse... vil svigte.“ Hvad betyder det?!\n\nVi må bringe det et sikkert sted hen, så vi kan undersøge det nærmere!", p="Pas på jer selv. Jeg mistænker, at disse konstruktioner vil være hårdere end vagten."},
  [98313] = {c="Nå, nå...\n\nDet er da en del at gennemgå! Men yderst spændende. YDERST spændende!\n\nDet vil tage mig et stykke tid, før jeg overhovedet får lagt en plan i denne sag. Kom igen en anden gang, så giver jeg dig de seneste nyheder. Indtil videre, modtag Opdagerligaens tak.", p="Undskyld, jeg har rasende travlt. Havde du brug for noget?"},
  [98319] = {c="Ak, den tølpe...\n\nTak for hjælpen, Selvsen. Jeg tror, vi har vores rapport."},
  [98321] = {c="Nu er det det! Takket være disse forsendelser vil smedjen arbejde uafbrudt på et øjeblik!", p="Vindigoer er grimme bæster. Det er bare godt, at alle minearbejderne slap ud af Den Tandløse Hule i ét stykke!"},
  [98322] = {c="Gl' Hvidskæg sendte dig, ikke?\n\nJeg har hans rapport, så det er fint. Hele den her situation er et rod!"},
  [98323] = {c="Helt oversvømmet? Hvorfor er jeg ikke overrasket.\n\nNå, det kommer også med i rapporten.\n\n<Senir lægger Grethes brev oven på sin bunke af noter>", p="Ah, du er kommet tilbage lige til tiden.\n\nHvad er der sket, dreng? Du ser ud, som om du har set et spøgelse."},
  [98326] = {c="Du er virkelig en redningsmand, Leif!\n\nMin mand ville more sig over mig, men jeg kunne ikke få mig selv til at fortælle ham, at han må tilbringe endnu en nat ved søen. Nu kan vi måske nyde et rigtig godt måltid.", p="Det bliver en varm dag i Dun Frostbakke, før jeg fortæller Pakston, at jeg har tabt alt hans lager til vindigoerne."},
  [98340] = {c="Sådan er det, Fader Cenarius.\n\n<Dendrit laver en hurtig, usynlig bevægelse i luften over ham. Et svagt glimt af glorie falder over ham.>\n\nHilsner igen, Kiy. Nu er det tid til at lære det næste naturperspektiv: katten. Jeg vil sætte dig på vejen til at forstå denne side af det druidiske liv, men ligesom bjørnen er det dig, der må tage denne lære til dig og udbrede den."},
  [98341] = {c="Hilsen, unge shen'dorei. Jeg er kommet til dig, fordi jeg mærker, at du er parat til at forsøge at finde ud af, om du forstår min åndelige natur.\n\nJeg vil stille dig over for prøven fra Azeroths Store Katteånd, men da du kommer fra Vindras, vil jeg personligt holde øje med dine fremskridt. Til sidst er det min form, du skal antage, og ikke Azeroths katteånds form.\n\nVi begynder."},
  [98342] = {c="Fremragende. Du har vist, at du forstår kattens sande natur, og at du kan indkapsle den snedighed, skjulthed og hukommelse der skal til for at antage min form.\n\nJeg anser dig nu for værdig til min velsignelse, unge YOUR_CLASS7.", p="Ah, du er tilbage. Jeg håber, du har medbragt relikvierne?"},
  [98362] = {c="Velkommen tilbage, Cory. Jeg fornemmer, at du har mødt Den Store Kat-ånd og med held bestået prøven. Alle druider må gennemgå den prøve, ånden stiller, selv om prøverne varierer fra generation til generation. Jeg er stolt af, at du har bestået den og ærer Den Store Kat-ånds visdom. Det er en gammel ånd, lige så dødelig som den er legesyg, selvom jeg fornemmer, at du allerede forstår denne ånds natur.\n\nNu vil jeg lære dig, hvordan man antager kattens skikkelse."},
  [98386] = {c="Er møllen virkelig så slem? Det er værre, end jeg troede.\n\nJeg er ikke særlig kræsen, men arbejdet er slemt nok uden edderkopper, der kidnapper mine arbejdere. Tak for hjælpen, Rotten!"},
  [98387] = {c="Godt arbejde, Erajna. Eftersom vi har skåret Sortklippe-orkerne af fra deres allierede på de Brændende Stepper, har de intet håb om at holde deres stilling her uden ordentlige forsyninger.", p="Det meste af det, du finder, må plyndres fra Søshire. Det vil glæde mig at vide, at vores folk trives, mens orkerne visner hen."},
  [98389] = {c="Det kan hjælpe udøveren Arrenm og mange andre med at se vores sande natur. Ligesom i vores tidligere liv lever vi for at tjene vores folk -- at beskytte dem med de gaver, Lyset giver os.\n\nMed tiden vil de se, at vi er lige så værdifulde for Den Mørke Frues planer som alle andre.\n\nMåtte Lyset være med dig."},
  [98393] = {c="Sådan er det, Fader Cenarius.\n\n<Dendrit laver en hurtig, usynlig bevægelse i luften over ham. Et svagt glimt af glorie falder over ham.>\n\nHilsner igen, Hans. Nu er det tid til at lære det næste naturperspektiv: katten. Jeg vil sætte dig på vejen til at forstå denne side af det druidiske liv, men ligesom bjørnen er det dig, der må omfavne denne lære og udbrede den."},
  [98397] = {c="Velkommen tilbage, Turq. Jeg fornemmer, at du har mødt Den Store Kat-ånd og med held bestået prøven. Alle druider må gennemgå den prøve, ånden stiller, selv om prøverne varierer fra generation til generation. Jeg er stolt af, at du har bestået den og lyttet til Den Store Kat-ånds visdom. Det er en gammel ånd, lige så farlig som den er morsom, selvom jeg fornemmer, at du allerede forstår denne ånds natur.\n\nNu vil jeg lære dig, hvordan man antager kattens skikkelse."},
  [98403] = {c="Jeg burde have vidst, at det blev brugt til at kvæle denne jords edderkopper.\n\nJeg har hørt hviske om, at stoffet er kilden til det meste af den korruption, der plager os. Selvom det ikke er originalen, er det en ældre prøve og kan give os mere information, end vi har fået indtil nu.\n\nNormalt ville jeg bede dig sende det til Darnassos til videre undersøgelse. Men det er bedst, hvis vi holder det hemmeligt for nu, ellers får Dolanår aldrig sit ry tilbage.\n\nJeg stoler fuldt ud på dig.", p="<Tallonkai Hurtigrod sænker stemmen.>\n\nGår Xethorr stadig frit omkring?"},
  [98404] = {c="Fremragende. Du har vist, at du forstår kattens sande natur, og at du kan legemliggøre den snedighed, snigen og vildskab der skal til for at antage min skikkelse.\n\nJeg anser dig nu for værdig til min velsignelse, unge YOUR_CLASS7.", p="Ah, du er tilbage. Jeg håber, du har bragt relikvierne med dig?"},
  [98405] = {c="Jeg ser, at du er kommet for at lære at trække kraft fra min ånd. Godt. Lad os se, om du er klar til at modtage min skikkelse."},
  [98407] = {c="Ret så pænt et lager har du her.\n\nSelvom det ikke løser vores problem her, kan jeg roligt sove, vel vidende at vi har afskrækket dem fra at rykke længere frem. Flot arbejde, Zurk.", p="En fuldstændig vurdering af hyænemændene er ikke komplet uden at tage fat på de værste af deres slags. Slå disse Tærskere!"},
  [98417] = {c="Åh nej... sådanne ord er ingen trøst for mig. Kurothel lever ikke bare vildt – for hver nat opfører den sig mere og mere som et vildt dyr.\n\nJeg frygter, at hviskenerne må være sande.", p="Hvad fandt du i bakkerne i vores skov?"},
  [98418] = {c="Jeg mærker, hvordan det vokser op i mig og omkring mig... Elunes lys. Jeg fornemmer, at Kurothel har set din gerning i denne krig, der raser i vores land og i vores hjerter.\n\nJeg håber, at vores Vogteres og de vildfarne druiders indsats med tiden for altid vil udrydde den dæmoniske pest. Først da vil den vilde glød fra hævnen brænde ud af vores slægts arv.\n\nTak, YOUR_NAME. Du er skovens allierede og en ven af det Kaldoriske folk."},
  [98423] = {c="Ah ja, min forfader Madoran var den første Bronzeskæg-konge af Jernsmede, efter den store borgerkrig mellem Vildhammer-, Bronzeskæg- og Mørkejern-klanerne. Denne traktat blev udfærdiget for at kodificere enden på fjendskabet og fredsvilkårene efter Bronzeskægenes sejr på bjerget.\n\nSom du kan se, underskrev Vildhamrene og Bronzeskæggene den... men Mørkejernene gjorde ikke.\n\nTak, fordi du fandt den og bragte den til mig, YOUR_CLASS7.", p="Hvad bringer du op fra dybet, YOUR_CLASS7."},
  [98427] = {c="Hele Blodhov-landsbyen står i gæld til dig i dag. Må Moder Jords nåde altid ledsage dig.", p="Er Hakkeren blevet stoppet, Dovahhajen?"},
  [98459] = {c="<Bjarne pakker gaven ud.>\n\nPfft, den skurk, den søn...\n\nEr det ikke ham, der snyder i poker?! Jeg vandt så mange penge til at købe Jomfruens Dyd, først efter at jeg smed ham ud af vores pokerkreds!\n\nJeg sværger, næste gang jeg ser den absolutte havspild–\n\nUndskyld, undskyld. Jeg skulle ikke have skudt budbringeren. På vegne af besætningen på Jomfruens Dyd – det bedste skib på Det Store Hav – velkommen til Menetil-havnen!", p="Giv den gas! Afsted på mit ord!\n\nHvad? Hvad har du dér, vandrer?"},
  [98461] = {c="<Tarrøl læser en seddel.>\n\nÅh... åh gud! Stakkels Hulle.\n\nHun har altid haft noget for mig. Og ærligt talt var der et øjeblik, hvor jeg kunne have mærket det. Men jeg er gift. Og lykkeligt gift!\n\nJeg tror, det bedste er ikke at svare. Jeg ved ikke, hvordan jeg skal sige det til hende, og jeg har langt vigtigere sager her! Min kone er forsvundet!", p="Hvad foregår der her?"},
  [98463] = {c="Jeg har det, du har brug for, makker! Bliv lidt, smid noget af det guld, der tynger din pung, og hyg dig.\n\nVelkommen til Kroen Den Salte Sømand!"},
  [98512] = {c="Jeg er glad for, at du er vendt tilbage i god behold. Den gruppe Al'Aketh så ud som iskolde skurke.\n\nTak for din hjælp, jeg tager din indsats med i min rapport, når jeg vender tilbage til Valanår.", p="Mon de ikke leder efter?"},
  [98545] = {c="Tak for at levere det her, gamle ven.\n\nVent... han sagde, at du fortjente drikkepenge? Det var jeg ikke med på!\n\nFint. Vælg dig noget af skraldet i hittegodset. Du ville blive overrasket over, hvor mange af de Forladte der efterlader ting efter deres frisørbesøg. Man laver en spøg om, at de er hjernedøde, men jeg mistænker, at spøgen i mange tilfælde faktisk er sand.", p="Hvad? Siger du, at Leonid sendte dig? Åh, dreng, jeg har ikke set den støvede gamle soldat siden dengang Naxxrammas regnede helvede ned over vores hoveder."},
  [98574] = {c="Med tiden og øvelse vil du opdage nye sider af Lyset. På en måde er det at finde en enhed mellem det, du tænker, og det, du føler. Når du uddyber din forbindelse til Lyset, kan du vende tilbage til mig for at tale om, hvad du har lært. Jeg vil med glæde vise dig, hvordan du bruger denne kraft til at lære dig at hele eller straffe de onde. For en lille donation, selvfølgelig!", p="Ah, endnu en YOUR_RACE7, der kommer for at lære om Lyset! Du vil opdage, at det at uddybe din forbindelse til Lyset handler om nysgerrighed og intelligens, egenskaber som mange gnomer har i rigt mål. Lysets vej er ikke en teknisk disciplin, men en gåde, der giver både livslektioner og praktiske velsignelser."},
  [98575] = {c="Du har lige fået et glimt af en magt, der kunne være din. De svage og dumme iblandt os er bange for den vej, vi træder, men med mod og snedighed kan vi bestemme vores egen skæbne.\n\nHold dine kræfter tæt ind til kroppen. De bange slår ud mod det, de ikke forstår.\n\nNu er du en af os. Hvis du har brug for at lære besvergelser, så kom tilbage til mig.", p="Ah, du har fået min besked. Udmærket. Vi orker har en lang og turbulent historie med Nether-væsnerne, men nu baner vi vores egen vej, under kontrol over vores egen skæbne. Du kan også tilegne dig kraften til at forme fremtiden for vores folk. Der hvor vores ledere falder, er vi klar til at rykke frem og tage vores retmæssige plads. Du vil blive fremtrædende blandt trolde."},
  [98581] = {c="Shamanistiske kunster blev bevaret af Vildhammer-klanen i årevis, og nu er de også kommet i Bronzeskæg-dværgenes varetægt. Jeg er her for at sprede disse læresætninger og give vejledning til nye shamaner, der lærer elementernes veje. Kom til mig, hvis du har brug for mere undervisning i jord-, luft-, ild- og vandbesværgelser.", p="Ah, kunne du læse runen? Den er gennemsyret af elementernes kraft fra nogle af vores ældste skrifter. Det viser, at du har YOUR_CLASS7-egenskaber."},
  [98601] = {c="Din læring kan nu begynde for alvor, YOUR_CLASS7. Jeg ser store løfter i dig, men pas på, at du ikke vender ryggen til lyset, ikke engang et øjeblik. Omfavn smerten, den vil forårsage dig. Denne smerte er en smeltedigel, og du vil komme ud af den stærkere, end du nogensinde var i dit tidligere liv.", p="Gennem smerte kommer fasthed."},
  [98739] = {c="<Dendrit laver endnu et usynligt håndtegn i luften over sig selv, når du nærmer dig. Endnu en glorie af kraft sænker sig over ham, og han smiler lidt.>\n\nJeg fornemmer kattens snedighed og vildskab i dig, som der ikke var, da jeg sendte dig for at møde Den Store Kattaånd. I dine øjne kan jeg mærke, at du nu forstår det snigende og den hurtighed, der kræves for at antage denne natur.\n\nNu kan du lære at samle din snedighed, antage kattens sande natur og kalde dens ånd."},
  [98815] = {c="Det er nogle af de bedste skind, jeg nogensinde har haft i hænderne; de vil få mine prydborter til at se fantastiske ud. Tak, YOUR_NAME.\n\nPrøv dem på og tag en til dig selv som betaling.", p="Velkommen tilbage, YOUR_CLASS7. Har du brug for læderolie til dit udstyr?"},
  [98823] = {c="Ak... dette fragment lyder med verdenens egen stemme. Lyset i dets indre er et minde fra fortiden, der blinker med historiens glimt. Denne titaniske maskine må have ventet i århundreder, til nogen forstod den.\n\nDu gjorde klogt i at bringe den til os. Jordens Kreds vil beskytte den, undersøge den og dele de sandheder, den gemmer på, når vi kan aflæse dens budskaber.\n\nI dag ærer du elementerne, vandrer.", p="Kom så. Led, og du skal finde."},
  [98824] = {c="Hvad er det for en genstand...\n\nWow! Se det vidunder! Lyset, der passerer igennem den, danser som intet, jeg har set siden min første udgravning i den gamle Uldhulen. Vagternes mærker på denne genstand kan ikke tages fejl af.\n\nDu har gjort Ligaen en stor tjeneste ved at bringe det hjem. Sådan et fund rykker verdens viden fremad.\n\nVi noterer detaljerne om dit bidrag! Virkelig fremragende arbejde, eventyrer.", p="Kig på vores galleri, men berør venligst ikke artefakterne, medmindre det er noget, du er kommet for at give til biblioteket."},
  [98887] = {c="Sandet på Mørke Spydøerne er gennemblødt af Alliancens blod, som du har udslettet. Godt klaret, YOUR_NAME.\n\nFor Horden!", p="Hvad er nyt fra Mørkespyd-øerne, YOUR_NAME?"},
  [98895] = {c="Du har udmærket dig med ære i slaget om Mørke Spydøerne, og din indsats er ikke gået ubemærket hen.\n\nDer er dog stadig flere kampe. Bliv ved med at bevise din værdi i kamp, så får du sikkert belønningerne.", p="Hvordan går din kampagne på Mørkespyd-øerne, YOUR_NAME?"},
  [98903] = {c="Theramore-ekspeditionsstyrken takker dig for din hengivenhed og tapperhed i slaget om Mørke Lansø-øerne, YOUR_NAME.\n\nFor Alliancen!"},
  [98906] = {c="Du har vist styrke og hengivenhed på Mørke Spydøerne! Dit mod i kamp er beundringsværdigt, makker!"},
  [99046] = {c="Elunies nåde... Jeg vil ikke dø... alene..."},
  [99048] = {c="Heglans lig ligger koldt i hyttens ruiner.\n\nUanset hvad der dræbte hende, ser det ikke ud til at have været mennesker. Der er nok spor af, hvad der skete et sted i nærheden."},
  [99049] = {c="Dette banner og stykke sværd tilhører nagaerne! De må have rejst langs kysten fra nord.\n\nVi kan ikke lade dem etablere et brohoved. Presset fra begge sider ville være for stort for Barberhøj.", p="Har du fundet hende?"},
  [99050] = {c="Tak for din hjælp. Værsgo, tag dette som hjælp til at dække omkostningerne for violerne og vandet.\n\nNu skal vi lave salven. Det burde kun tage et øjeblik.", p="Har du ingredienserne? Jeg frygter, at Eralya måske ikke har meget tid tilbage."},
  [99051] = {c="Jeg håber, at det sender dem tilbage mod nord. Jeg lader nogle soldater holde øje med alle flygtninge og mistænkelig færd.", p="Jeg håber, at de slangeskum ikke volder dig besvær?"},
  [99052] = {c="Ha! Jeg kunne høre hans krop falde herfra!\n\nVær stolt af dagens drab, for ikke mange kan prale af at have overlevet en kamp mod en havgigant.", p="Giv dem blod og torden!"},
  [99053] = {c="Tak Elunie, fordi du var her for at hjælpe Lysesa med at undgå en mørk skæbne fra Knudefyr. Hun er en af vores bedste og min personlige veninde.\n\nVær så venlig at tage imod dette som en tak. Må det hjælpe dig med at holde nattebørnene i sikkerhed."},
  [99073] = {c="<Eralyas vejrtrækning falder hurtigt til ro, mens du hjælper hende med at tage salven. Hun overlever måske ikke, men hun er relativt rolig.>", p="<Eralya holder op med at svare med ord. Kun et svagt, rallende åndedrag bekræfter, at hun lever.>"},
  [99123] = {c="Ah, Pal'jøh er havnet i problemer igen, ikke sandt?\n\nJeg håber, at hun lærer lektien om at handle alene denne gang. Tak for hendes hjælp. Hun er en lovende jæger, hun har bare en tendens til at opføre sig mere som en rovfugl end en tiger."},
  [99127] = {c="Er alle nettene sådan? Det ser ud til, at vores nye irriterende naboer laver mere ravage, end vi var klar over. Jeg bliver ruineret, hvis vi ikke gør noget ved det.", p="Er der nogen fangster at fortælle om?"},
  [99128] = {c="Jeg hører deres hvæsen overalt, de vil helt sikkert hjemsøge mine mareridt. Nåja, det burde bremse dem, selvom jeg ikke tvivler på, at de formerer sig hurtigt.", p="Er de allerede døde?"},
  [99129] = {c="Jeg advarede vagterne om murlokkerne. De vil ikke lytte.\n\nJeg har et par ideer til, hvordan vi kan gøre kål på de skabninger. Men jeg får brug for din hjælp til at skaffe det, jeg skal bruge."},
  [99130] = {c="Giv mig et øjeblik...\n\nDet er et ret simpelt lokkemiddel, men så længe ingen lader kæledyret slippe ind, bør det være sikkert. Bare sig til Jason, at han ikke må spise noget af det.", p="Har du fundet alt endnu?"},
  [99131] = {c="Giftagn? Så længe fiskene spiser den, burde det lykkes. Jeg kommer forbi Remi senere for at hente den."},
  [99134] = {c="Der er ikke meget glæde at hente i døden. Heldigvis er smerte den vigtigste af dem.\n\nDu tilfredsstiller mig i dag, og dermed tilfredsstiller du Den Mørke Frue. Måske bliver du nyttig i fremtiden."},
  [99141] = {c="Jeg burde have vidst, at en abomination ikke ville skrive noget nyttigt. Lad os glemme min forsømmelse, du og jeg.\n\nDu tilfredsstiller mig, og dermed tilfredsstiller du Den Mørke Frue. Måske er der håb for dig.", p="Du må hellere have de rapporter i hånden, ellers hold dig væk fra mig."},
  [99142] = {c="Den aller sande storhed!\n\n<Juniorapoteker Holland inspicerer ukrudtet.>\n\nHmm, jeg havde håbet, de ville modnes lidt mere gennem vold. Men fremskridt er fremskridt!\n\nMange mennesker vil dø som følge af dine handlinger i dag. Du bør være stolt af dig selv.", p="Flere afbrydelser! Vent, det er dig. Var du i stand til at hente gravukrudtet?"},
  [99143] = {c="Interessant samling. Disse burde klare sig godt nok!\n\nDe her er noget af mit ældre lager. Det burde hjælpe enhver, der prøver at finde sig en plads i fiskeriet.", p="Hvad fandt du? Noget interessant?"},
  [99144] = {c="Velsignelser over dig for din hjælp til Lysbæreren. Vores orden er stadig ved at rodfæste sig her, og det ville være en katastrofe at miste et så lovende medlem.\n\nTag venligst dette som et tegn på vores taknemmelighed. Hvis vores veje nogensinde skulle friste dig, ligger vores kloster, Bandarion-borgen, ude på klipperne mod nordvest for Solliden-gården. Vi byder velkommen enhver, der søger vejledning på Lysets vej."},
  [99152] = {c="Godt gjort, rekrut. Vi kan lige nu gøre noget ud af dig.\n\nMed disse knogler kan vi måske bedre forstå, hvordan en sådan trussel kunne slippe upåagtet igennem så længe.", p="Du må hellere ikke komme tilbage med tomme hænder. Enten har jeg brug for de knogler, jeg bad om, eller din krop på en båre, så jeg kan bekræfte, at du i det mindste prøvede at skaffe dem."},
  [99153] = {c="Godt gjort -- og hurtigt til! Nu til min yndlingsdel...", p="Har du fundet den forbandede ting endnu?"},
  [99156] = {c="Du er et vidnesbyrd om den snildhed og koordination, som alle de Forladte besidder - noget den underudviklede Pest aldrig vil få.\n\nVær venlig at tage dette som en tak for din indsats, som lovet.", p="Har du allerede taget dig af vores lille problem?"},
  [99158] = {c="Ah. Stearinlys fra Jernsmede.\n\nSelvom jeg for det meste kan klare mig selv i min eremitage, er der nogle få vigtige ting, jeg sætter pris på fra byen og fra de fromme.", p="Hvorfor førte Lyset dig hertil i dag?"},
  [99159] = {c="Ah, ideelt. De duer -- dem, der er for våde til at bruge nu, lader jeg tørre.\n\nHvis du nu er villig, har jeg flere opgaver, hvor jeg måske får brug for din hjælp.", p="Lyset lede dig i dine opgaver."},
  [99160] = {c="Jeg skulle ønske, vi bare kunne have formildet dem. Desværre lå det uden for min viden, og de var for farlige til at lade dem løbe løs ukontrolleret."},
  [99161] = {c="Lyset velsigne dig, YOUR_CLASS7. Dine anstrengelser gør dette sted langt tryggere, og vi håber, de forhindrer unødige dødsfald.", p="'Pas på vinteren, ven."},
  [99162] = {c="Højlænderne graverer deres navne ind i kolben på deres geværer. Det hjælper med at identificere dem, hvis der sker noget. Jeg sender dem tilbage til Jernsmede -- der vil nogen give dem videre til familierne.", p="Hvad har du brug for?"},
}
for id, t in pairs(extra) do
    local q = ns.Quests[id]
    if q then
        if t.p and not q.p then q.p = t.p end
        if t.c and not q.c then q.c = t.c end
    end
end
